/* CSEC Study Hub — practice bank
 *
 * These questions are written for this hub in CSEC Paper 01 style. They are not
 * copies of CXC past papers — CXC owns those and sells them, so the hub links
 * out to the official store rather than reproducing them. Every item is tagged
 * to a syllabus strand so a wrong answer moves the right strand in the mastery
 * model and comes back in the daily plan.
 *
 * Fields: id, subj, strand, form (earliest form it fits), diff 1-3,
 *         q, opts[], a (index of correct option), why, tech (exam technique)
 */
window.CSEC_QUESTIONS = [

/* ============================ MATHEMATICS ============================ */
{id:'ma1',subj:'mathematics',strand:'ma-number',level:6,diff:1,q:'Simplify: 3/4 + 2/5',opts:['23/20','5/9','23/40','6/20'],a:0,why:'Use a common denominator of 20: 3/4 = 15/20 and 2/5 = 8/20. 15/20 + 8/20 = 23/20, which is 1 3/20.',tech:'Never add denominators. Find the LCM first, convert both, then add only the numerators.'},
{id:'ma2',subj:'mathematics',strand:'ma-number',level:7,diff:2,q:'Write 0.00045 in standard form.',opts:['4.5 × 10⁻⁴','45 × 10⁻⁵','4.5 × 10⁴','0.45 × 10⁻³'],a:0,why:'Standard form needs one non-zero digit before the point. Moving the point 4 places right gives 4.5, so the index is −4.',tech:'Small number → negative index. Large number → positive index. Count the jumps of the decimal point.'},
{id:'ma3',subj:'mathematics',strand:'ma-number',level:7,diff:1,q:'Evaluate (2³)²',opts:['64','32','12','36'],a:0,why:'Power of a power means multiply the indices: (2³)² = 2⁶ = 64.',tech:'Multiply indices for a power of a power; add them when multiplying the same base.'},
{id:'ma4',subj:'mathematics',strand:'ma-consumer',level:7,diff:2,q:'A television is marked $2 400 before VAT. VAT is charged at 12.5%. What is the price including VAT?',opts:['$2 700.00','$2 412.50','$2 550.00','$3 000.00'],a:0,why:'VAT = 12.5% of 2 400 = $300. Total = 2 400 + 300 = $2 700.',tech:'Adding a percentage? Multiply by 1.125 in one step instead of finding the VAT and adding it — fewer chances to slip.'},
{id:'ma5',subj:'mathematics',strand:'ma-consumer',level:8,diff:2,q:'Kavita borrows $8 000 at 5% simple interest per annum for 3 years. How much interest does she pay?',opts:['$1 200','$400','$1 260','$2 400'],a:0,why:'Simple interest I = PRT/100 = (8 000 × 5 × 3)/100 = $1 200.',tech:'Read whether the question wants the interest or the total amount repaid. It is the commonest lost mark in this topic.'},
{id:'ma6',subj:'mathematics',strand:'ma-sets',level:7,diff:2,q:'In a class of 40 students, 25 study Spanish and 18 study French. 7 study both. How many study neither?',opts:['4','3','11','15'],a:0,why:'Students doing at least one = 25 + 18 − 7 = 36. Neither = 40 − 36 = 4.',tech:'Draw the Venn diagram and fill the intersection FIRST, then work outwards. Subtract the overlap so it is not counted twice.'},
{id:'ma7',subj:'mathematics',strand:'ma-measure',level:7,diff:2,q:'Find the area of a circle of radius 7 cm. Use π = 22/7.',opts:['154 cm²','44 cm²','49 cm²','308 cm²'],a:0,why:'A = πr² = 22/7 × 7 × 7 = 154 cm².',tech:'Area uses r², circumference uses 2r. Mixing them up is the single commonest circle error.'},
{id:'ma8',subj:'mathematics',strand:'ma-measure',level:8,diff:2,q:'A cylinder has radius 3 cm and height 10 cm. Taking π = 3.14, find its volume.',opts:['282.6 cm³','94.2 cm³','188.4 cm³','90 cm³'],a:0,why:'V = πr²h = 3.14 × 9 × 10 = 282.6 cm³.',tech:'Volume of any prism or cylinder = area of the cross-section × length. Learn one rule, not five.'},
{id:'ma9',subj:'mathematics',strand:'ma-stats',level:7,diff:1,q:'Find the mean of: 4, 7, 9, 12, 3',opts:['7','9','8','6'],a:0,why:'Sum = 35, and there are 5 values, so the mean = 35 ÷ 5 = 7.',tech:'Mean = add and divide. Median = order first, then take the middle. Mode = most frequent. Write the three definitions on your paper before you start the question.'},
{id:'ma10',subj:'mathematics',strand:'ma-stats',level:8,diff:2,q:'A bag contains 3 red and 5 blue marbles. One marble is drawn at random. What is the probability that it is red?',opts:['3/8','3/5','5/8','1/3'],a:0,why:'P(red) = number of red ÷ total = 3 ÷ 8 = 3/8.',tech:'The denominator is always the TOTAL. Count everything in the bag before you write the fraction.'},
{id:'ma11',subj:'mathematics',strand:'ma-algebra',level:6,diff:1,q:'Solve: 3x − 7 = 14',opts:['x = 7','x = 21','x = 2⅓','x = 3'],a:0,why:'Add 7 to both sides: 3x = 21. Divide by 3: x = 7.',tech:'Undo in reverse order — clear the addition or subtraction first, then the multiplication.'},
{id:'ma12',subj:'mathematics',strand:'ma-algebra',level:8,diff:2,q:'Factorise completely: x² + 5x + 6',opts:['(x + 2)(x + 3)','(x + 1)(x + 6)','(x − 2)(x − 3)','(x + 5)(x + 1)'],a:0,why:'Two numbers that multiply to 6 and add to 5 are 2 and 3, giving (x + 2)(x + 3).',tech:'Multiply your brackets back out to check. It takes ten seconds and catches every sign error.'},
{id:'ma13',subj:'mathematics',strand:'ma-algebra',level:8,diff:2,q:'Solve the pair: x + y = 10 and x − y = 4',opts:['x = 7, y = 3','x = 3, y = 7','x = 6, y = 4','x = 5, y = 5'],a:0,why:'Adding the equations eliminates y: 2x = 14, so x = 7. Substituting back gives y = 3.',tech:'When the same letter has opposite signs, ADD to eliminate. Same signs, subtract.'},
{id:'ma14',subj:'mathematics',strand:'ma-algebra',level:9,diff:3,q:'Solve: x² − 5x + 6 = 0',opts:['x = 2 or x = 3','x = −2 or x = −3','x = 1 or x = 6','x = 5 or x = 6'],a:0,why:'Factorising gives (x − 2)(x − 3) = 0, so x = 2 or x = 3.',tech:'A quadratic has two answers. Writing only one loses half the marks even when that one is right.'},
{id:'ma15',subj:'mathematics',strand:'ma-relations',level:8,diff:2,q:'Find the gradient of the line joining (1, 2) and (3, 8).',opts:['3','2','1/3','6'],a:0,why:'Gradient = (8 − 2) ÷ (3 − 1) = 6 ÷ 2 = 3.',tech:'Gradient is rise over run — the y difference on top. Taking them the other way up is the classic slip.'},
{id:'ma16',subj:'mathematics',strand:'ma-geom',level:7,diff:2,q:'What is the sum of the interior angles of a hexagon?',opts:['720°','1080°','540°','360°'],a:0,why:'Sum = (n − 2) × 180° = (6 − 2) × 180° = 720°.',tech:'Interior sum = (n − 2) × 180°. The EXTERIOR angles of any polygon always add to 360°.'},
{id:'ma17',subj:'mathematics',strand:'ma-geom',level:8,diff:2,q:'A right-angled triangle has legs of 6 cm and 8 cm. Find the hypotenuse.',opts:['10 cm','14 cm','48 cm','7 cm'],a:0,why:'By Pythagoras, h² = 6² + 8² = 36 + 64 = 100, so h = 10 cm.',tech:'The hypotenuse is always opposite the right angle and always the longest side. If your answer is smaller than a leg, it is wrong.'},
{id:'ma18',subj:'mathematics',strand:'ma-geom',level:9,diff:2,q:'What is the value of sin 30°?',opts:['0.5','1','0.866','0.577'],a:0,why:'sin 30° = 1/2 = 0.5. It comes from the half of an equilateral triangle.',tech:'Learn the exact values for 30°, 45° and 60°. They appear every year and save calculator time.'},
{id:'ma19',subj:'mathematics',strand:'ma-number',level:7,diff:1,q:'Divide $600 in the ratio 2 : 3. What is the LARGER share?',opts:['$360','$240','$300','$400'],a:0,why:'Total parts = 5, so one part = $120. The larger share is 3 parts = $360.',tech:'Always find the value of ONE part first. Then read carefully whether the question wants the larger or smaller share.'},
{id:'ma20',subj:'mathematics',strand:'ma-vectors',level:9,diff:3,q:'If a = (3, 1) and b = (−1, 4), find a + b.',opts:['(2, 5)','(4, −3)','(2, −3)','(−3, 4)'],a:0,why:'Add the matching components: (3 + (−1), 1 + 4) = (2, 5).',tech:'Add vectors component by component — never multiply them out. Keep the columns lined up on your page.'},

/* ============================ ENGLISH A ============================ */
{id:'ea1',subj:'english-a',strand:'ea-grammar',level:6,diff:1,q:'Choose the correct sentence.',opts:['Neither of the boys has finished his work.','Neither of the boys have finished their work.','Neither of the boys have finished his work.','Neither of the boys has finished their work.'],a:0,why:'"Neither" is singular, so it takes the singular verb "has" and the singular pronoun "his". The phrase "of the boys" does not change the subject.',tech:'Cover the phrase between the subject and the verb. The verb must agree with what is left.'},
{id:'ea2',subj:'english-a',strand:'ea-grammar',level:7,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The students’ books were collected.','The students books’ were collected.','The student’s books were collected by all forty of them.','The students’s books were collected.'],a:0,why:'For a plural noun already ending in s, the apostrophe goes after the s: students’.',tech:'Ask who owns it. If the owner is plural and ends in s, apostrophe after. If singular, apostrophe then s.'},
{id:'ea3',subj:'english-a',strand:'ea-grammar',level:7,diff:2,q:'Identify the sentence with a dangling modifier.',opts:['Walking to school, the rain soaked Amara.','Walking to school, Amara was soaked by the rain.','As Amara walked to school, the rain soaked her.','Amara was soaked by the rain as she walked to school.'],a:0,why:'The opening phrase must describe the subject that follows. As written, the rain is walking to school.',tech:'After an -ing opening, the very next noun must be the one doing it. Check that noun every time.'},
{id:'ea4',subj:'english-a',strand:'ea-vocab',level:7,diff:2,q:'"The politician gave a *terse* reply." The word "terse" most nearly means:',opts:['brief and abrupt','long and detailed','warm and friendly','confused and unclear'],a:0,why:'Terse means using few words, often to the point of curtness.',tech:'When a word is unfamiliar, read the whole sentence for tone. The surrounding words usually narrow it to one option.'},
{id:'ea5',subj:'english-a',strand:'ea-comp',level:7,diff:2,q:'A question asks you to state what the writer IMPLIES about a character. This means you should:',opts:['work out what the writer suggests without stating directly','copy the sentence that describes the character','give your own opinion of the character','summarise the whole passage'],a:0,why:'To imply is to suggest indirectly. You infer it from the evidence rather than lifting a stated line.',tech:'"State" means lift it. "Suggest", "imply" or "infer" means work it out and then quote the evidence you used.'},
{id:'ea6',subj:'english-a',strand:'ea-summary',level:8,diff:3,q:'In a CSEC summary question, which is the MOST important rule?',opts:['Use your own words and keep within the word limit','Copy the best sentences from the passage','Include every example the writer gives','Write as much as you can to be safe'],a:0,why:'The summary tests whether you can identify main ideas and re-express them concisely in your own words within the stated limit.',tech:'Underline the main idea of each paragraph, then write one sentence per idea. Count your words — going over loses marks.'},
{id:'ea7',subj:'english-a',strand:'ea-arg',level:8,diff:2,q:'Which is the strongest thesis statement for an argumentative essay?',opts:['Secondary schools should ban mobile phones during class time because they measurably reduce concentration.','This essay is about mobile phones in school.','Mobile phones are a very interesting topic today.','There are many opinions about mobile phones in schools.'],a:0,why:'A thesis takes a clear, arguable position and signals the reason. The others announce a topic without arguing anything.',tech:'Your thesis must be something a reasonable person could disagree with. If nobody could argue back, it is not a thesis.'},
{id:'ea8',subj:'english-a',strand:'ea-narr',level:7,diff:2,q:'Which opening best shows rather than tells?',opts:['Her hands shook as she reached for the envelope.','She was very nervous about the envelope.','She felt nervous and worried and scared.','The envelope made her feel extremely nervous.'],a:0,why:'The physical detail of shaking hands lets the reader conclude she is nervous. The others simply name the emotion.',tech:'Show through action, gesture and detail. Naming the feeling is the fastest way to a mid-band mark.'},
{id:'ea9',subj:'english-a',strand:'ea-persuade',level:9,diff:2,q:'You must write a letter to the Principal requesting a change to the timetable. Which register is appropriate?',opts:['Formal and respectful, with a clear request and reasons','Casual and friendly, as if writing to a classmate','Emotional and demanding','Very short, with no explanation'],a:0,why:'Audience and purpose set register. A Principal is a formal audience, so the letter needs formal courtesy and reasoned support.',tech:'Before writing a directed piece, note the audience, purpose and format in the margin. Marks are awarded for all three.'},
{id:'ea10',subj:'english-a',strand:'ea-grammar',level:8,diff:2,q:'Which sentence is in the passive voice?',opts:['The report was written by the committee.','The committee wrote the report.','The committee is writing the report.','The committee will write the report.'],a:0,why:'In the passive, the subject receives the action. "The report" receives the writing, and the doer follows "by".',tech:'Passive = a form of "to be" + past participle. Useful in formal writing, but overusing it makes essays limp.'},

/* ============================ ENGLISH B ============================ */
{id:'eb1',subj:'english-b',strand:'eb-devices',level:6,diff:1,q:'"The wind whispered through the cane." This is an example of:',opts:['personification','simile','hyperbole','onomatopoeia'],a:0,why:'The wind is given a human ability — whispering — so it is personification.',tech:'Personification gives a human quality to something non-human. Simile needs "like" or "as".'},
{id:'eb2',subj:'english-b',strand:'eb-devices',level:6,diff:1,q:'"He was as stubborn as a mule." This is:',opts:['a simile','a metaphor','personification','an oxymoron'],a:0,why:'The comparison uses "as", which makes it a simile. A metaphor would say he WAS a mule.',tech:'Like or as → simile. Direct statement of one thing being another → metaphor.'},
{id:'eb3',subj:'english-b',strand:'eb-devices',level:7,diff:2,q:'"I have told you a million times." This is:',opts:['hyperbole','understatement','irony','alliteration'],a:0,why:'Hyperbole is deliberate exaggeration for effect — the speaker has not literally spoken a million times.',tech:'Do not just name the device. Say what EFFECT it creates — that is where the marks are.'},
{id:'eb4',subj:'english-b',strand:'eb-poetry',level:7,diff:2,q:'A poem with the rhyme scheme ABAB CDCD EFEF GG in fourteen lines is MOST likely:',opts:['a Shakespearean sonnet','a ballad','free verse','a haiku'],a:0,why:'Fourteen lines in three quatrains and a closing couplet with that scheme is the Shakespearean (English) sonnet form.',tech:'Count the lines first, then map the rhyme with letters down the margin. Form often points straight at the theme.'},
{id:'eb5',subj:'english-b',strand:'eb-poetry',level:7,diff:2,q:'The MOOD of a poem refers to:',opts:['the feeling the poem creates in the reader','the poet’s attitude to the subject','the number of syllables per line','the rhyme scheme'],a:0,why:'Mood is the atmosphere felt by the reader. The poet’s attitude is TONE — a different thing.',tech:'Tone belongs to the speaker, mood belongs to the reader. Examiners test that you can tell them apart.'},
{id:'eb6',subj:'english-b',strand:'eb-prose',level:8,diff:2,q:'In a novel, the term "protagonist" means:',opts:['the central character whose story we follow','the character who opposes the hero','the narrator of the story','the author’s spokesperson'],a:0,why:'The protagonist is the main character. The one who opposes them is the antagonist.',tech:'Do not assume the protagonist is likeable or the narrator. Many novels separate these deliberately.'},
{id:'eb7',subj:'english-b',strand:'eb-drama',level:8,diff:3,q:'Dramatic irony occurs when:',opts:['the audience knows something a character does not','a character says the opposite of what is meant','the ending is unexpected','two characters argue on stage'],a:0,why:'Dramatic irony depends on the gap between the audience’s knowledge and the character’s, which builds tension.',tech:'Verbal irony is in the words, situational irony is in the outcome, dramatic irony is in who knows what.'},
{id:'eb8',subj:'english-b',strand:'eb-essay',level:8,diff:3,q:'In a literature essay, the strongest paragraph structure is:',opts:['Point, Evidence, Explanation','Evidence, Point, Summary','Story retelling, then opinion','Quotation, then the next quotation'],a:0,why:'State the point, support it with a short quotation, then explain how that quotation proves the point and links to the question.',tech:'The Explanation is where most students lose marks. Never let a quotation stand without saying what it proves.'},
{id:'eb9',subj:'english-b',strand:'eb-short',level:7,diff:2,q:'Short stories usually differ from novels because they:',opts:['concentrate on a single effect or moment','always have a happy ending','contain no dialogue','are written only in the first person'],a:0,why:'The compressed form pushes a short story towards one central incident, effect or revelation.',tech:'In a short-story question, identify the turning point early — most questions circle back to it.'},
{id:'eb10',subj:'english-b',strand:'eb-devices',level:8,diff:2,q:'"The sea is a hungry dog" is:',opts:['a metaphor','a simile','alliteration','assonance'],a:0,why:'The sea is stated to BE a dog, with no "like" or "as", which makes it a metaphor.',tech:'When asked to comment on a metaphor, explain what quality is transferred — here, restless appetite and threat.'}
];

/* ===================== SCIENCES, HUMANITIES, LANGUAGES, TECHNICAL ===================== */
window.CSEC_QUESTIONS.push(

/* ---------------------------- PHYSICS ---------------------------- */
{id:'ph1',subj:'physics',strand:'ph-measure',level:6,diff:1,q:'The SI unit of force is the:',opts:['newton','joule','watt','pascal'],a:0,why:'Force is measured in newtons (N). The joule is energy, the watt is power and the pascal is pressure.',tech:'Learn the unit with the quantity from Form 1. Paper 01 gives away marks for units every single year.'},
{id:'ph2',subj:'physics',strand:'ph-mech',level:7,diff:1,q:'A runner covers 100 m in 20 s. What is the average speed?',opts:['5 m/s','2 000 m/s','0.2 m/s','20 m/s'],a:0,why:'Speed = distance ÷ time = 100 ÷ 20 = 5 m/s.',tech:'Write the formula, substitute, then compute. Examiners award a mark for the correct formula even if the arithmetic slips.'},
{id:'ph3',subj:'physics',strand:'ph-mech',level:7,diff:2,q:'A block has mass 200 g and volume 100 cm³. Find its density.',opts:['2 g/cm³','0.5 g/cm³','20 000 g/cm³','100 g/cm³'],a:0,why:'Density = mass ÷ volume = 200 ÷ 100 = 2 g/cm³.',tech:'Check the units match before dividing. Grams with cm³, kilograms with m³ — never mix them.'},
{id:'ph4',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'Newton’s Third Law states that:',opts:['for every action there is an equal and opposite reaction','force equals mass times acceleration','an object stays at rest unless acted on by a force','energy cannot be created or destroyed'],a:0,why:'The Third Law describes paired forces acting on two different bodies, equal in size and opposite in direction.',tech:'The action-reaction pair acts on DIFFERENT objects. That is why they never cancel each other out.'},
{id:'ph5',subj:'physics',strand:'ph-waves',level:8,diff:2,q:'A wave has frequency 50 Hz and wavelength 2 m. Find its speed.',opts:['100 m/s','25 m/s','52 m/s','0.04 m/s'],a:0,why:'v = fλ = 50 × 2 = 100 m/s.',tech:'v = fλ is the one wave equation you must never forget. Rearrange it rather than learning three versions.'},
{id:'ph6',subj:'physics',strand:'ph-waves',level:7,diff:1,q:'When light reflects from a plane mirror, the angle of incidence is:',opts:['equal to the angle of reflection','twice the angle of reflection','always 90°','always zero'],a:0,why:'The law of reflection states that the angle of incidence equals the angle of reflection, both measured from the normal.',tech:'Both angles are measured from the NORMAL, not from the mirror surface. Draw the normal first.'},
{id:'ph7',subj:'physics',strand:'ph-elec',level:8,diff:2,q:'A 12 V supply drives current through a 4 Ω resistor. What is the current?',opts:['3 A','48 A','0.33 A','8 A'],a:0,why:'By Ohm’s law, I = V ÷ R = 12 ÷ 4 = 3 A.',tech:'V = IR. Cover the quantity you want with your finger to see whether to multiply or divide.'},
{id:'ph8',subj:'physics',strand:'ph-thermal',level:9,diff:2,q:'Latent heat is the energy needed to:',opts:['change the state of a substance without changing its temperature','raise the temperature of a substance','melt only solids','boil only liquids'],a:0,why:'During a change of state, the energy supplied breaks bonds between particles rather than raising temperature.',tech:'On a heating curve, the flat sections are where latent heat is being absorbed. Point to them in your answer.'},
{id:'ph9',subj:'physics',strand:'ph-atom',level:9,diff:3,q:'A radioactive sample has a half-life of 5 days. What fraction remains after 15 days?',opts:['1/8','1/3','1/15','1/5'],a:0,why:'15 days is three half-lives. After each one the amount halves: 1 → 1/2 → 1/4 → 1/8.',tech:'Count how many half-lives fit into the time given, then halve that many times. Never divide by the number of days.'},
{id:'ph10',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'The moment of a force about a point is calculated as:',opts:['force × perpendicular distance from the point','force ÷ distance','force + distance','mass × acceleration'],a:0,why:'Moment = F × d, where d is the perpendicular distance from the pivot to the line of action of the force.',tech:'The distance must be PERPENDICULAR. If the force is at an angle, resolve it or use the perpendicular distance.'},

/* ---------------------------- CHEMISTRY ---------------------------- */
{id:'ch1',subj:'chemistry',strand:'ch-matter',level:6,diff:1,q:'Which method best separates sand from water?',opts:['filtration','distillation','chromatography','evaporation'],a:0,why:'Sand is insoluble, so it stays on the filter paper while water passes through as the filtrate.',tech:'Ask whether the solid dissolves. Insoluble → filter. Soluble and you want the solid → evaporate. Want the liquid → distil.'},
{id:'ch2',subj:'chemistry',strand:'ch-matter',level:7,diff:2,q:'Which technique would you use to separate the dyes in a sample of ink?',opts:['paper chromatography','filtration','decanting','magnetic separation'],a:0,why:'Chromatography separates dissolved substances by how far each travels up the paper with the solvent.',tech:'Always draw the pencil baseline ABOVE the solvent level. A pen line would dissolve and ruin the run.'},
{id:'ch3',subj:'chemistry',strand:'ch-atomic',level:7,diff:1,q:'The atomic number of an element tells you the number of:',opts:['protons in the nucleus','neutrons in the nucleus','protons and neutrons together','electron shells'],a:0,why:'Atomic number = proton number. In a neutral atom it also equals the number of electrons.',tech:'Mass number − atomic number = neutrons. Write that line at the top of the page in every structure question.'},
{id:'ch4',subj:'chemistry',strand:'ch-atomic',level:8,diff:2,q:'An ionic bond is formed when:',opts:['electrons are transferred from a metal to a non-metal','electrons are shared between two non-metals','protons move between atoms','atoms exchange neutrons'],a:0,why:'The metal loses electrons to form a positive ion and the non-metal gains them to form a negative ion; opposite charges attract.',tech:'Metal + non-metal → ionic. Non-metal + non-metal → covalent. That one line answers most bonding questions.'},
{id:'ch5',subj:'chemistry',strand:'ch-acids',level:7,diff:1,q:'A solution with pH 3 is:',opts:['acidic','alkaline','neutral','a strong base'],a:0,why:'The pH scale runs 0 to 14. Below 7 is acidic, 7 is neutral and above 7 is alkaline.',tech:'The LOWER the pH, the STRONGER the acid. Students routinely reverse this under pressure.'},
{id:'ch6',subj:'chemistry',strand:'ch-acids',level:8,diff:2,q:'Complete the general equation: acid + base →',opts:['salt + water','salt + hydrogen','salt + carbon dioxide + water','hydrogen + oxygen'],a:0,why:'Neutralisation of an acid by a base produces a salt and water only.',tech:'Acid + metal → salt + hydrogen. Acid + carbonate → salt + water + carbon dioxide. Learn all three pairs together.'},
{id:'ch7',subj:'chemistry',strand:'ch-mole',level:9,diff:2,q:'What is the relative molecular mass of water, H₂O? (H = 1, O = 16)',opts:['18','17','32','20'],a:0,why:'(2 × 1) + 16 = 18.',tech:'Multiply each atomic mass by the number of that atom BEFORE adding. The subscript applies only to the atom it follows.'},
{id:'ch8',subj:'chemistry',strand:'ch-organic',level:9,diff:2,q:'The general formula of the alkanes is:',opts:['CₙH₂ₙ₊₂','CₙH₂ₙ','CₙH₂ₙ₋₂','CₙHₙ'],a:0,why:'Alkanes are saturated hydrocarbons with only single bonds, giving CₙH₂ₙ₊₂. Alkenes are CₙH₂ₙ.',tech:'Alkane = all single bonds, saturated. Alkene = one double bond, unsaturated, decolourises bromine water.'},
{id:'ch9',subj:'chemistry',strand:'ch-inorg',level:9,diff:2,q:'A gas turns limewater milky. The gas is:',opts:['carbon dioxide','oxygen','hydrogen','ammonia'],a:0,why:'Carbon dioxide reacts with limewater (calcium hydroxide) to form insoluble calcium carbonate, which makes it cloudy.',tech:'Learn the four gas tests as a set: CO₂ milky limewater, O₂ relights a glowing splint, H₂ pops, NH₃ turns damp red litmus blue.'},
{id:'ch10',subj:'chemistry',strand:'ch-redox',level:9,diff:3,q:'During electrolysis, positive ions move towards the:',opts:['cathode','anode','electrolyte','battery'],a:0,why:'Positive ions (cations) are attracted to the negative electrode, which is the cathode, where they gain electrons.',tech:'Remember PANIC — Positive is Anode, Negative Is Cathode. Then cations go to the cathode.'},

/* ---------------------------- BIOLOGY ---------------------------- */
{id:'bi1',subj:'biology',strand:'bi-cells',level:6,diff:1,q:'Which structure is found in a plant cell but NOT in an animal cell?',opts:['cell wall','nucleus','cytoplasm','cell membrane'],a:0,why:'The cellulose cell wall, chloroplasts and a large permanent vacuole are plant features. All four options exist in both, except the cell wall.',tech:'Learn the three plant-only structures as a set: cell wall, chloroplast, large vacuole.'},
{id:'bi2',subj:'biology',strand:'bi-cells',level:7,diff:2,q:'Osmosis is the movement of:',opts:['water from high to low water potential through a partially permeable membrane','any substance from high to low concentration','water against a concentration gradient using energy','solutes through a membrane'],a:0,why:'Osmosis is specifically water moving down its water-potential gradient through a partially permeable membrane.',tech:'Say WATER and say PARTIALLY PERMEABLE MEMBRANE. A definition missing either word rarely scores full marks.'},
{id:'bi3',subj:'biology',strand:'bi-nutri',level:7,diff:2,q:'Which are the raw materials for photosynthesis?',opts:['carbon dioxide and water','oxygen and glucose','glucose and water','nitrogen and water'],a:0,why:'Carbon dioxide + water, in the presence of light and chlorophyll, produce glucose and oxygen.',tech:'Write the word equation before answering any photosynthesis question. It settles inputs versus outputs instantly.'},
{id:'bi4',subj:'biology',strand:'bi-nutri',level:8,diff:2,q:'Enzymes are:',opts:['proteins that speed up reactions and are affected by temperature and pH','carbohydrates that provide energy','lipids that store energy','minerals used in respiration'],a:0,why:'Enzymes are protein catalysts. High temperature or the wrong pH denatures the active site.',tech:'Use the word DENATURED, not "killed". Enzymes are molecules, not living things — that wording costs marks.'},
{id:'bi5',subj:'biology',strand:'bi-resp',level:8,diff:2,q:'The products of aerobic respiration in humans are:',opts:['carbon dioxide, water and energy','lactic acid and energy','glucose and oxygen','alcohol and carbon dioxide'],a:0,why:'Glucose + oxygen → carbon dioxide + water + energy. Lactic acid comes from ANAEROBIC respiration in muscle.',tech:'Anaerobic in muscle gives lactic acid; in yeast it gives alcohol and CO₂. Keep the two organisms separate.'},
{id:'bi6',subj:'biology',strand:'bi-nutri',level:7,diff:1,q:'Red blood cells transport oxygen because they contain:',opts:['haemoglobin','plasma','platelets','antibodies'],a:0,why:'Haemoglobin binds oxygen to form oxyhaemoglobin in the lungs and releases it in the tissues.',tech:'Match each blood component to its job: red cells oxygen, white cells defence, platelets clotting, plasma transport.'},
{id:'bi7',subj:'biology',strand:'bi-env',level:6,diff:1,q:'In a food chain, the first organism is always:',opts:['a producer','a herbivore','a carnivore','a decomposer'],a:0,why:'Food chains begin with a producer — usually a green plant that makes its own food by photosynthesis.',tech:'The arrows in a food chain show the direction ENERGY flows, not who eats whom. Draw them pointing away from the producer.'},
{id:'bi8',subj:'biology',strand:'bi-genes',level:9,diff:3,q:'A plant with genotype Tt is crossed with tt. What proportion of offspring will be tall if T is dominant?',opts:['50%','100%','75%','25%'],a:0,why:'The Punnett square gives Tt, Tt, tt, tt — half carry the dominant allele, so 50% are tall.',tech:'Always draw the Punnett square. An answer without it loses the method marks even when the ratio is right.'},
{id:'bi9',subj:'biology',strand:'bi-resp',level:8,diff:2,q:'Which is an example of EXCRETION rather than egestion?',opts:['removal of urea in urine','removal of faeces from the anus','removal of undigested fibre','removal of food that was never absorbed'],a:0,why:'Excretion removes waste made by the body’s own metabolism, such as urea. Egestion removes material that was never absorbed.',tech:'If the body MADE it, that is excretion. If it merely passed through, that is egestion.'},
{id:'bi10',subj:'biology',strand:'bi-health',level:8,diff:2,q:'Which disease is caused by a vector-borne virus common in the Caribbean?',opts:['dengue','diabetes','anaemia','asthma'],a:0,why:'Dengue is a viral disease transmitted by the Aedes aegypti mosquito, which is the vector. The others are not infectious.',tech:'Name the pathogen AND the vector when a question asks about transmission. Both carry marks.'},

/* ---------------------------- GEOGRAPHY ---------------------------- */
{id:'ge1',subj:'geography',strand:'ge-maps',level:6,diff:2,q:'When giving a grid reference, you read:',opts:['eastings first, then northings','northings first, then eastings','the largest number first','the contour value first'],a:0,why:'The convention is along the corridor then up the stairs — eastings (across) before northings (up).',tech:'"Along the corridor, up the stairs." Say it out loud in the exam; it prevents a reversed reference.'},
{id:'ge2',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'On a map, contour lines drawn very close together indicate:',opts:['a steep slope','a gentle slope','flat land','a valley floor'],a:0,why:'Closely spaced contours mean a large height change over a short horizontal distance, which is a steep slope.',tech:'Close = steep, wide = gentle. Check the contour interval in the key before describing any relief.'},
{id:'ge3',subj:'geography',strand:'ge-tectonic',level:8,diff:2,q:'Volcanoes and earthquakes in the Eastern Caribbean occur mainly at a:',opts:['destructive (convergent) plate boundary','constructive plate boundary','conservative plate boundary','the centre of a plate'],a:0,why:'The Atlantic plate subducts beneath the Caribbean plate, producing the volcanic island arc of the Lesser Antilles.',tech:'Name the actual plates in your answer — Atlantic and Caribbean. Generic answers score in the lowest band.'},
{id:'ge4',subj:'geography',strand:'ge-weather',level:7,diff:1,q:'The Atlantic hurricane season officially runs from:',opts:['1 June to 30 November','1 January to 30 June','1 March to 31 August','1 September to 31 December'],a:0,why:'The official Atlantic hurricane season is 1 June to 30 November, when sea temperatures and conditions favour formation.',tech:'Learn the conditions needed too: sea above about 27 °C, low wind shear, and distance from the equator for the Coriolis effect.'},
{id:'ge5',subj:'geography',strand:'ge-weather',level:8,diff:2,q:'Relief rainfall occurs when:',opts:['moist air is forced to rise over high ground, cools and condenses','the ground heats and air rises by convection','two air masses of different temperature meet','cold air sinks over the sea'],a:0,why:'Air forced up a mountain barrier cools, condenses and rains on the windward side, leaving a rain shadow to leeward.',tech:'Three rainfall types: relief, convectional and frontal. Say which side is windward and name the rain shadow.'},
{id:'ge6',subj:'geography',strand:'ge-pop',level:7,diff:2,q:'Population density is calculated as:',opts:['total population ÷ land area','total population × land area','births minus deaths','population ÷ number of households'],a:0,why:'Density is people per square kilometre — population divided by area.',tech:'Density is how crowded; distribution is where people are. Questions often ask for one and students answer the other.'},
{id:'ge7',subj:'geography',strand:'ge-econ',level:8,diff:2,q:'Which is Trinidad and Tobago’s most important export sector by value?',opts:['petroleum and petrochemicals','tourism','agriculture','textiles'],a:0,why:'Oil, natural gas and downstream petrochemicals such as ammonia and methanol dominate the country’s export earnings.',tech:'For any Caribbean economy question, know one named example in detail rather than four in outline.'},
{id:'ge8',subj:'geography',strand:'ge-hazard',level:8,diff:2,q:'Which is a MITIGATION measure against earthquake damage?',opts:['enforcing building codes for earthquake-resistant construction','issuing a warning one hour before','evacuating after the shaking stops','rebuilding in the same way afterwards'],a:0,why:'Mitigation reduces impact before an event. Earthquakes cannot yet be predicted, so resistant construction is the main defence.',tech:'Separate preparation, mitigation and response in your notes. Questions almost always name one of the three.'},

/* ---------------------------- HISTORY ---------------------------- */
{id:'hi1',subj:'history',strand:'hi-indigenous',level:6,diff:1,q:'The indigenous people who mainly settled the Greater Antilles before European contact were the:',opts:['Taino','Maya','Aztec','Inca'],a:0,why:'The Taino occupied the Greater Antilles and the Bahamas. The Kalinago were concentrated in the Lesser Antilles.',tech:'Keep Taino and Kalinago straight by geography — Greater Antilles versus Lesser Antilles.'},
{id:'hi2',subj:'history',strand:'hi-indigenous',level:6,diff:1,q:'Columbus first reached the Caribbean in the year:',opts:['1492','1592','1445','1502'],a:0,why:'Columbus made landfall in the Bahamas in October 1492 on his first voyage.',tech:'Anchor the syllabus to a handful of dates: 1492, 1834, 1838, 1845, 1937, 1962. Everything else hangs off them.'},
{id:'hi3',subj:'history',strand:'hi-slavery',level:7,diff:2,q:'The Sugar Revolution in the Caribbean led MOST directly to:',opts:['a large increase in the demand for enslaved African labour','the end of plantation agriculture','the growth of small peasant farms','a decline in European settlement'],a:0,why:'Sugar required large estates and heavy year-round labour, which planters met by massively expanding the trade in enslaved Africans.',tech:'"Most directly" means pick the immediate consequence, not a later one. Read that phrase carefully.'},
{id:'hi4',subj:'history',strand:'hi-slavery',level:7,diff:2,q:'The Middle Passage refers to the:',opts:['voyage of enslaved Africans across the Atlantic to the Americas','journey of sugar from the Caribbean to Europe','march of captives to the African coast','return voyage of ships to Europe'],a:0,why:'It is the middle leg of the triangular trade, carrying enslaved Africans from West Africa to the Americas.',tech:'Be able to name all three legs of the triangular trade and the cargo on each.'},
{id:'hi5',subj:'history',strand:'hi-resist',level:8,diff:2,q:'The Haitian Revolution (1791–1804) is significant because it:',opts:['produced the first independent Black republic in the world','restored French control of Saint-Domingue','ended slavery throughout the Caribbean at once','was led by British abolitionists'],a:0,why:'The revolution defeated French, Spanish and British forces and established Haiti as the first Black republic in 1804.',tech:'Link Toussaint Louverture and Dessalines to their stages of the revolution. Named leaders lift an essay out of the middle band.'},
{id:'hi6',subj:'history',strand:'hi-emanc',level:8,diff:2,q:'Full freedom for the formerly enslaved in the British Caribbean came in:',opts:['1838, at the end of apprenticeship','1834, when the Act took effect','1833, when the Act was passed','1845'],a:0,why:'Emancipation took effect in 1834 but bound most people to apprenticeship. Full freedom came when apprenticeship ended in 1838.',tech:'1833 passed, 1834 in force, 1838 full freedom. Examiners test whether you know all three are different.'},
{id:'hi7',subj:'history',strand:'hi-adjust',level:8,diff:2,q:'The first ship carrying Indian indentured immigrants to Trinidad arrived in 1845. It was the:',opts:['Fatel Razack','Mayflower','Windrush','Santa Maria'],a:0,why:'The Fatel Razack arrived on 30 May 1845, an event now marked as Indian Arrival Day in Trinidad and Tobago.',tech:'For a Trinidad-based candidate this is a gift topic. Know the push and pull factors behind indentureship as well as the date.'},
{id:'hi8',subj:'history',strand:'hi-indep',level:9,diff:2,q:'The labour disturbances of 1937 in Trinidad were led in the oilfields by:',opts:['Uriah "Buzz" Butler','Eric Williams','Norman Manley','Alexander Bustamante'],a:0,why:'Butler led the oilfield workers’ protests of 1937, which fed directly into the growth of the trade union movement.',tech:'The 1930s labour unrest is the bridge from colonial rule to independence. Every "movements towards independence" essay should mention it.'},
{id:'hi9',subj:'history',strand:'hi-indep',level:9,diff:2,q:'The West Indies Federation existed between:',opts:['1958 and 1962','1945 and 1950','1962 and 1970','1973 and 1980'],a:0,why:'The Federation was formed in 1958 and dissolved in 1962 after Jamaica’s withdrawal following its referendum.',tech:'Do not confuse the Federation (1958–62) with CARICOM (1973). They are different bodies with different aims.'},
{id:'hi10',subj:'history',strand:'hi-skills',level:7,diff:2,q:'When a History question says "Explain TWO reasons", the best approach is to:',opts:['state each reason and develop it with specific evidence','list as many reasons as you can remember','describe the events in the order they happened','give your personal opinion'],a:0,why:'"Explain" requires reasons developed with supporting detail. Listing without development scores in the lowest band.',tech:'If it says TWO, give exactly two and develop both. A third undeveloped reason earns nothing and costs time.'},

/* ------------------------- SOCIAL STUDIES ------------------------- */
{id:'ss1',subj:'social-studies',strand:'ss-family',level:6,diff:1,q:'A family consisting of a mother, father and their children only is called a:',opts:['nuclear family','extended family','sibling household','single-parent family'],a:0,why:'The nuclear family is two parents and their children. Adding grandparents, aunts or uncles makes it extended.',tech:'Learn the family types with one Caribbean example each. Examples are what separate a Grade I from a Grade III.'},
{id:'ss2',subj:'social-studies',strand:'ss-family',level:7,diff:2,q:'Which is the PRIMARY agent of socialisation?',opts:['the family','the school','the media','peer groups'],a:0,why:'The family is primary because it is the first and most influential agent, shaping values before any other institution.',tech:'Primary means first and most formative. School, peers, media and religion are secondary agents.'},
{id:'ss3',subj:'social-studies',strand:'ss-region',level:8,diff:2,q:'CARICOM was established by the Treaty of Chaguaramas in:',opts:['1973','1958','1962','1989'],a:0,why:'The Treaty of Chaguaramas established the Caribbean Community and Common Market in 1973.',tech:'1973 CARICOM, 1989 Grand Anse Declaration leading to the CSME. Two dates, two different achievements.'},
{id:'ss4',subj:'social-studies',strand:'ss-region',level:8,diff:2,q:'The CSME is intended to allow the free movement of:',opts:['goods, services, capital and skilled labour','goods only','people on holiday only','currency only'],a:0,why:'The CARICOM Single Market and Economy provides for free movement of goods, services, capital and approved categories of skilled labour.',tech:'Note that labour movement is for APPROVED CATEGORIES, not everyone. That precision earns the mark.'},
{id:'ss5',subj:'social-studies',strand:'ss-gov',level:7,diff:2,q:'In Trinidad and Tobago, the arm of government that makes laws is the:',opts:['legislature','judiciary','executive','civil service'],a:0,why:'The legislature (Parliament) makes law, the executive implements it and the judiciary interprets it.',tech:'Three arms, three verbs: make, implement, interpret. That sentence answers half the government questions.'},
{id:'ss6',subj:'social-studies',strand:'ss-research',level:9,diff:2,q:'In an SBA, the statement of the problem should:',opts:['clearly identify what is being investigated and where','list all your findings','thank everyone who helped','describe your conclusion'],a:0,why:'The statement of the problem sets out the specific issue, the location and the scope of the investigation.',tech:'Keep the statement narrow enough to research with one questionnaire. Broad topics cannot be evidenced and lose marks.'},

/* ---------------------------- SPANISH ---------------------------- */
{id:'sp1',subj:'spanish',strand:'sp-gram',level:6,diff:1,q:'Complete: "Yo ___ estudiante."',opts:['soy','estoy','tengo','es'],a:0,why:'"Ser" is used for permanent characteristics and identity, so "yo soy estudiante".',tech:'SER for identity, origin and permanent traits. ESTAR for location and temporary states. It is tested every year.'},
{id:'sp2',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'Complete: "La biblioteca ___ cerca de la escuela."',opts:['está','es','son','tiene'],a:0,why:'Location always takes "estar", so "la biblioteca está cerca".',tech:'If the sentence says WHERE something is, use estar — with no exceptions at CSEC level.'},
{id:'sp3',subj:'spanish',strand:'sp-gram',level:8,diff:2,q:'What is the "yo" form of "hablar" in the preterite tense?',opts:['hablé','hablo','hablaba','hablaré'],a:0,why:'The preterite yo form of an -ar verb ends in -é: hablé (I spoke).',tech:'Preterite = completed action. Imperfect = used to / was doing. The accent on -é is part of the mark.'},
{id:'sp4',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'"¿Cómo te llamas?" means:',opts:['What is your name?','How are you?','Where do you live?','How old are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the person’s name.',tech:'Learn the core question words as a block: qué, quién, dónde, cuándo, cómo, por qué, cuánto.'},
{id:'sp5',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'Which is the correct definite article: "___ casa"?',opts:['la','el','los','las'],a:0,why:'"Casa" is a feminine singular noun, so it takes "la".',tech:'Most nouns ending in -a are feminine and -o masculine. Learn the exceptions (el día, la mano) as a short list.'},
{id:'sp6',subj:'spanish',strand:'sp-read',level:7,diff:2,q:'A sign reads "PROHIBIDO FUMAR". It means:',opts:['No smoking','No entry','No parking','No photographs'],a:0,why:'"Prohibido" means forbidden and "fumar" means to smoke.',tech:'In the reading paper, signs and notices come first and are the quickest marks. Do not rush them.'},

/* ---------------------------- FRENCH ---------------------------- */
{id:'fr1',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Complete: "Je ___ quatorze ans."',opts:['ai','suis','est','as'],a:0,why:'French expresses age with "avoir" — j’ai quatorze ans, literally "I have fourteen years".',tech:'Age, hunger, thirst and fear all use AVOIR in French, not être. English speakers reach for "suis" and lose the mark.'},
{id:'fr2',subj:'french',strand:'fr-gram',level:8,diff:2,q:'Which auxiliary does "aller" take in the passé composé?',opts:['être','avoir','faire','venir'],a:0,why:'"Aller" is one of the verbs of motion that take "être": je suis allé(e).',tech:'Learn the être verbs with DR & MRS VANDERTRAMP, and remember the past participle must agree with the subject.'},
{id:'fr3',subj:'french',strand:'fr-themes',level:6,diff:1,q:'"Comment t’appelles-tu ?" means:',opts:['What is your name?','How old are you?','Where are you from?','How are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the name.',tech:'Do not confuse it with "Comment ça va ?" which asks how you are.'},
{id:'fr4',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Which is the correct definite article: "___ école"?',opts:['l’','le','la','les'],a:0,why:'"École" begins with a vowel, so le/la elides to l’.',tech:'Before a vowel or silent h, le and la both become l’. The gender still matters for adjective agreement.'},
{id:'fr5',subj:'french',strand:'fr-read',level:7,diff:2,q:'A notice reads "DÉFENSE DE STATIONNER". It means:',opts:['No parking','No smoking','No entry','Do not touch'],a:0,why:'"Stationner" means to park, and "défense de" means it is forbidden.',tech:'"Défense de" and "interdit" both mean forbidden. Learn the common public notices — they are free marks.'},
{id:'fr6',subj:'french',strand:'fr-write',level:8,diff:2,q:'In a CSEC directed writing task with a 130–150 word limit, writing 200 words will:',opts:['lose marks, because the limit is part of the task','gain marks for extra detail','make no difference','only matter in the oral'],a:0,why:'The word limit is a stated requirement; exceeding it is penalised regardless of quality.',tech:'Count in blocks of ten as you write. Finishing inside the limit is worth more than one extra idea.'},

/* -------------------------- VISUAL ARTS -------------------------- */
{id:'va1',subj:'visual-arts',strand:'va-elements',level:6,diff:1,q:'The three primary colours are:',opts:['red, yellow and blue','red, green and blue','orange, green and purple','black, white and grey'],a:0,why:'In pigment, red, yellow and blue cannot be mixed from other colours and combine to make the secondaries.',tech:'Primary → secondary → tertiary. Be ready to name which two primaries make each secondary.'},
{id:'va2',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Which pair are complementary colours?',opts:['red and green','red and orange','blue and purple','yellow and orange'],a:0,why:'Complementary colours sit opposite each other on the colour wheel. Red faces green, blue faces orange, yellow faces purple.',tech:'Complementary pairs placed together intensify each other. Say that effect when you use the term in a critique.'},
{id:'va3',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Balance, rhythm, contrast and unity are:',opts:['principles of design','elements of art','types of media','art movements'],a:0,why:'Elements are the building blocks — line, shape, colour, texture, form, space, value. Principles are how they are arranged.',tech:'Elements are WHAT you use, principles are HOW you arrange them. Critique questions want both.'},
{id:'va4',subj:'visual-arts',strand:'va-draw',level:8,diff:2,q:'In one-point perspective, all receding parallel lines converge at:',opts:['a single vanishing point on the horizon','two vanishing points','the centre of the paper','the top corner'],a:0,why:'One-point perspective has a single vanishing point on the eye-level horizon line.',tech:'Draw the horizon line and mark the vanishing point before anything else. Freehand guessing is visible to the examiner.'},

/* ------------------- PHYSICAL EDUCATION & SPORT ------------------- */
{id:'pe1',subj:'physical-education',strand:'pe-fitness',level:6,diff:1,q:'Which is a component of HEALTH-related fitness?',opts:['cardiovascular endurance','agility','reaction time','coordination'],a:0,why:'Health-related components are cardiovascular endurance, muscular strength, muscular endurance, flexibility and body composition. Agility, reaction time and coordination are skill-related.',tech:'Learn the five health-related and six skill-related components as two separate lists. Questions test the split.'},
{id:'pe2',subj:'physical-education',strand:'pe-injury',level:7,diff:1,q:'RICE, the immediate treatment for a soft-tissue injury, stands for:',opts:['Rest, Ice, Compression, Elevation','Run, Ice, Cool, Exercise','Rest, Injure, Cool, Extend','Rest, Immobilise, Cover, Elevate'],a:0,why:'Rest, Ice, Compression and Elevation limit swelling and pain in the first 48 hours after a sprain or strain.',tech:'Be able to say WHY each step works — reduces blood flow, limits swelling. Naming alone is a one-mark answer.'},
{id:'pe3',subj:'physical-education',strand:'pe-fitness',level:7,diff:2,q:'The FITT principle stands for:',opts:['Frequency, Intensity, Time, Type','Fitness, Interval, Training, Technique','Force, Impact, Tempo, Timing','Flexibility, Intensity, Training, Type'],a:0,why:'FITT is the framework for designing a training programme: how often, how hard, how long and what kind.',tech:'Apply FITT to a named sport in your answer. Generic programmes score low.'},
{id:'pe4',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Which is NOT a function of the skeleton?',opts:['production of hormones for growth','support of the body','protection of vital organs','production of blood cells'],a:0,why:'The skeleton supports, protects, allows movement, stores minerals and makes blood cells in the marrow. Hormones are made by the endocrine glands.',tech:'"NOT" questions catch tired candidates. Underline the word NOT before you look at the options.'},
{id:'pe5',subj:'physical-education',strand:'pe-nutri',level:7,diff:2,q:'Which nutrient is the body’s MAIN source of energy for high-intensity exercise?',opts:['carbohydrate','protein','fat','vitamins'],a:0,why:'Carbohydrate is broken down to glucose, the fastest fuel available and the one used at high intensity.',tech:'Fat fuels low-intensity endurance work; protein is for growth and repair, not a main fuel.'},

/* --------------------- INFORMATION TECHNOLOGY --------------------- */
{id:'it1',subj:'information-technology',strand:'it-hardware',level:6,diff:1,q:'Which of the following is an INPUT device?',opts:['scanner','monitor','printer','speaker'],a:0,why:'A scanner sends data into the computer. Monitors, printers and speakers all output data.',tech:'Ask which way the data flows — into the machine is input, out of it is output.'},
{id:'it2',subj:'information-technology',strand:'it-hardware',level:7,diff:2,q:'RAM is described as volatile because it:',opts:['loses its contents when power is removed','can be written to only once','stores data permanently','is slower than the hard disk'],a:0,why:'Volatile memory needs continuous power. Switch the machine off and RAM is cleared; ROM and disk storage are not.',tech:'RAM volatile and temporary, ROM non-volatile and permanent. One sentence, several marks a year.'},
{id:'it3',subj:'information-technology',strand:'it-data',level:7,diff:2,q:'The binary number 1011 is equal to which decimal number?',opts:['11','13','9','15'],a:0,why:'Place values 8, 4, 2, 1 give (1×8) + (0×4) + (1×2) + (1×1) = 11.',tech:'Write the place values 8 4 2 1 above the digits before converting. It removes the guesswork.'},
{id:'it4',subj:'information-technology',strand:'it-solve',level:8,diff:2,q:'In a flowchart, the diamond shape represents:',opts:['a decision','a process','input or output','the start or end'],a:0,why:'The diamond is a decision with two exit paths, normally labelled Yes and No.',tech:'Oval start/stop, parallelogram input/output, rectangle process, diamond decision. Label BOTH branches of every diamond.'},
{id:'it5',subj:'information-technology',strand:'it-productivity',level:7,diff:2,q:'In a spreadsheet, which formula adds the values in cells A1 to A10?',opts:['=SUM(A1:A10)','=ADD(A1:A10)','=TOTAL(A1-A10)','=SUM(A1+A10)'],a:0,why:'SUM with a colon range adds every cell from A1 through A10 inclusive.',tech:'Every formula starts with =. The colon means a RANGE; a comma means a list of separate cells.'},
{id:'it6',subj:'information-technology',strand:'it-impact',level:8,diff:2,q:'Checking that a date of birth entered as 32/13/2011 is impossible is an example of:',opts:['validation','verification','encryption','compression'],a:0,why:'Validation checks that data is reasonable and within allowed limits. Verification checks it was copied accurately.',tech:'Validation = sensible. Verification = accurate. Give an example of each and the marks follow.'},
{id:'it7',subj:'information-technology',strand:'it-solve',level:9,diff:3,q:'In an IPO chart, the "P" stands for:',opts:['Processing','Program','Print','Procedure'],a:0,why:'IPO stands for Input, Processing and Output — the three stages of defining a problem before designing an algorithm.',tech:'Fill the Output column first. Knowing what you must produce tells you what inputs and processing you need.'}
);

/* ===================== Launch top-up — brings every default subject to 12+ ===================== */
window.CSEC_QUESTIONS.push(

/* ------------------------------- SPANISH ------------------------------- */
{id:'sp7',subj:'spanish',strand:'sp-gram',level:6,diff:1,q:'Which is the correct plural: "___ libros"?',opts:['los','las','el','la'],a:0,why:'"Libro" is masculine, so the masculine plural article is "los".',tech:'Singular el/la become plural los/las. The noun takes -s (or -es after a consonant).'},
{id:'sp8',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'"Tengo que estudiar" means:',opts:['I have to study','I want to study','I am studying','I studied'],a:0,why:'"Tener que" + infinitive expresses obligation — to have to do something.',tech:'Learn the three obligation forms together: tener que, hay que, deber. They are examined most years.'},
{id:'sp9',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'"Voy a comer" means:',opts:['I am going to eat','I ate','I eat every day','I would eat'],a:0,why:'"Ir a" + infinitive is the near future — going to do something.',tech:'The near future is far more common in speech than the true future tense. Use it in the oral.'},
{id:'sp10',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'Choose the correct form: "la casa ___"',opts:['blanca','blanco','blancos','blancas'],a:0,why:'Adjectives agree with the noun. "Casa" is feminine singular, so "blanca".',tech:'Check gender AND number on every adjective. It is the commonest slip in the writing paper.'},
{id:'sp11',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'What is "treinta y cinco" in figures?',opts:['35','25','45','53'],a:0,why:'Treinta is 30 and cinco is 5, joined by "y" to give 35.',tech:'Numbers 16-29 are written as one word; 31 upwards use "y". Prices and times depend on these.'},
{id:'sp12',subj:'spanish',strand:'sp-themes',level:7,diff:2,q:'"Me gusta el fútbol" literally means:',opts:['football is pleasing to me','I like to play football','I am playing football','football is mine'],a:0,why:'Gustar works backwards from English: the thing liked is the subject. Understanding this stops the classic errors with gustar.',tech:'Singular thing → me gusta. Plural things → me gustan. Say it aloud before you write it.'},

/* -------------------------------- FRENCH -------------------------------- */
{id:'fr7',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Which is the plural definite article in French?',opts:['les','le','la','un'],a:0,why:'Le and la both become "les" in the plural, whatever the gender.',tech:'French plural nouns usually add -s but it is silent. The article is what you hear.'},
{id:'fr8',subj:'french',strand:'fr-themes',level:6,diff:1,q:'"Il fait froid" means:',opts:['it is cold','he is cold','it is hot','he is making something'],a:0,why:'Weather uses "il fait" — it makes. "Il fait froid" is "it is cold".',tech:'Learn the weather block as fixed phrases: il fait beau, il fait chaud, il pleut, il neige.'},
{id:'fr9',subj:'french',strand:'fr-gram',level:7,diff:2,q:'"Je vais manger" means:',opts:['I am going to eat','I ate','I eat','I was eating'],a:0,why:'"Aller" + infinitive is the futur proche — going to do something.',tech:'The futur proche is safer than the future tense in the oral and is fully acceptable.'},
{id:'fr10',subj:'french',strand:'fr-gram',level:7,diff:2,q:'Choose the correct form: "une ___ maison"',opts:['petite','petit','petits','petites'],a:0,why:'"Maison" is feminine singular, so the adjective takes the feminine singular form "petite".',tech:'Most French adjectives follow the noun, but a short group — petit, grand, bon, beau, jeune — comes before it.'},
{id:'fr11',subj:'french',strand:'fr-themes',level:6,diff:1,q:'What is "quarante" in figures?',opts:['40','14','44','30'],a:0,why:'Quarante is 40. Quatorze is 14 — the two are easily confused.',tech:'Say the number aloud. Quatorze and quarante sound different even though they look similar.'},
{id:'fr12',subj:'french',strand:'fr-write',level:8,diff:2,q:'In the French oral examination, if you do not understand the question you should:',opts:['politely ask the examiner to repeat it in French','stay silent','answer in English','guess and change the subject'],a:0,why:'"Pouvez-vous répéter, s’il vous plaît ?" keeps you in French and loses no marks. Silence scores nothing.',tech:'Learn three repair phrases before the oral. Using them well shows control of the language.'},

/* ---------------------------- SOCIAL STUDIES ---------------------------- */
{id:'ss7',subj:'social-studies',strand:'ss-family',level:6,diff:1,q:'A household containing parents, children, grandparents and an aunt is a:',opts:['extended family','nuclear family','single-parent family','sibling household'],a:0,why:'An extended family includes relatives beyond the parents and children.',tech:'Caribbean examples matter here — extended and grandparent-headed households are common and worth naming.'},
{id:'ss8',subj:'social-studies',strand:'ss-gov',level:8,diff:2,q:'Universal adult suffrage means:',opts:['every adult citizen has the right to vote','only property owners may vote','voting is compulsory','only men may vote'],a:0,why:'It is the right of all adult citizens to vote regardless of race, sex, religion or property. Trinidad and Tobago gained it in 1946.',tech:'Know the date for your own country. Examiners reward local specificity.'},
{id:'ss9',subj:'social-studies',strand:'ss-dev',level:8,diff:2,q:'Sustainable development is best defined as development that:',opts:['meets present needs without compromising future generations','produces the fastest possible economic growth','uses only renewable resources','avoids all industry'],a:0,why:'The standard definition balances present needs against the ability of future generations to meet theirs.',tech:'Quote the definition, then give a Caribbean example — reef protection, reforestation, solar.'},
{id:'ss10',subj:'social-studies',strand:'ss-issues',level:7,diff:2,q:'Which is a PUSH factor causing migration from a country?',opts:['high unemployment at home','better schools abroad','family already living abroad','a higher wage abroad'],a:0,why:'Push factors drive people away from the source; pull factors attract them to the destination. Unemployment at home pushes.',tech:'Sort every factor into push or pull before writing. Questions usually ask for one or the other, not both.'},
{id:'ss11',subj:'social-studies',strand:'ss-issues',level:8,diff:2,q:'Which is a consumer RIGHT rather than a responsibility?',opts:['the right to be informed about a product','checking the expiry date','reading the warranty','complaining through the proper channel'],a:0,why:'Rights are what the consumer is owed; responsibilities are what the consumer must do. Being informed is a right.',tech:'Learn the rights and responsibilities as two matched lists. Questions test whether you can separate them.'},
{id:'ss12',subj:'social-studies',strand:'ss-gov',level:8,diff:2,q:'A pressure group differs from a political party because it:',opts:['seeks to influence policy without seeking to govern','contests general elections','forms the government','appoints judges'],a:0,why:'Pressure groups lobby for a cause; parties contest elections in order to govern.',tech:'Name a real Caribbean pressure group — a trade union or an environmental body — to lift the answer.'},

/* ------------------------------ VISUAL ARTS ------------------------------ */
{id:'va5',subj:'visual-arts',strand:'va-elements',level:6,diff:1,q:'Which set are the secondary colours?',opts:['orange, green, purple','red, yellow, blue','black, white, grey','brown, pink, cream'],a:0,why:'Secondary colours are made by mixing two primaries: red+yellow=orange, blue+yellow=green, red+blue=purple.',tech:'Be ready to state which two primaries make each secondary — that is the usual follow-up.'},
{id:'va6',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Adding white to a colour produces a:',opts:['tint','shade','tone','hue'],a:0,why:'White makes a tint, black makes a shade, grey makes a tone. Hue is the colour itself.',tech:'Four words, four meanings. Use them correctly in a critique and the vocabulary marks follow.'},
{id:'va7',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Reds, oranges and yellows are described as:',opts:['warm colours','cool colours','neutral colours','complementary colours'],a:0,why:'Warm colours suggest heat and advance towards the viewer; blues and greens are cool and recede.',tech:'Warm advances, cool recedes. That single fact explains most questions about depth in a painting.'},
{id:'va8',subj:'visual-arts',strand:'va-draw',level:7,diff:2,q:'In figure drawing, the adult human body is conventionally about how many heads tall?',opts:['seven to eight','four','twelve','five'],a:0,why:'The standard canon is roughly seven and a half to eight head-lengths for an adult.',tech:'Measure with your pencil held at arm’s length. Proportion errors are the first thing an examiner notices.'},
{id:'va9',subj:'visual-arts',strand:'va-elements',level:8,diff:2,q:'Texture that you can see but not feel is called:',opts:['implied texture','actual texture','relief texture','impasto'],a:0,why:'Implied (visual) texture is created with mark-making on a smooth surface; actual texture can be felt.',tech:'In a critique, say which kind of texture and how it was made — hatching, stippling, dry brush.'},
{id:'va10',subj:'visual-arts',strand:'va-print',level:8,diff:2,q:'In relief printing, the ink sits on:',opts:['the raised surface that was not cut away','the lines cut into the block','the whole block evenly','the paper before printing'],a:0,why:'In relief printing — lino and woodcut — you cut away what should stay white, and the raised surface takes the ink.',tech:'Remember the print is a mirror image. Any lettering must be cut in reverse.'},
{id:'va11',subj:'visual-arts',strand:'va-elements',level:8,diff:2,q:'The focal point of a composition is:',opts:['the area the eye is drawn to first','the exact centre of the page','the darkest area','the largest shape'],a:0,why:'The focal point is where the artist directs attention, through contrast, placement, colour or line. It need not be central or largest.',tech:'When asked how an artist creates a focal point, name the device — contrast, converging lines, isolation.'},
{id:'va12',subj:'visual-arts',strand:'va-history',level:9,diff:2,q:'Caribbean art of the twentieth century is most often discussed in terms of:',opts:['identity, heritage and the post-colonial experience','classical Greek proportion','Renaissance perspective','Dutch still life'],a:0,why:'Caribbean artists have consistently worked with questions of identity, African and Indian heritage, landscape and independence.',tech:'Know two named Caribbean artists and one work each. A general answer about "culture" scores in the lowest band.'},

/* --------------------- PHYSICAL EDUCATION & SPORT --------------------- */
{id:'pe6',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Muscles that work in antagonistic pairs mean that:',opts:['as one contracts the other relaxes','both contract together','both relax together','one replaces the other'],a:0,why:'Muscles pull but cannot push, so they work in pairs — the biceps and triceps at the elbow are the standard example.',tech:'Always name the pair AND the joint. "Biceps and triceps at the elbow" earns more than "arm muscles".'},
{id:'pe7',subj:'physical-education',strand:'pe-fitness',level:7,diff:2,q:'The main purpose of a warm-up is to:',opts:['raise body temperature and blood flow to reduce injury risk','tire the muscles before play','lose weight','practise the rules'],a:0,why:'A warm-up gradually raises heart rate, muscle temperature and joint mobility, which lowers the risk of strains.',tech:'Describe the three stages: pulse-raiser, mobility, sport-specific. A one-line answer loses marks.'},
{id:'pe8',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Anaerobic activity is BEST described as:',opts:['short, high-intensity effort without enough oxygen','long, steady effort using oxygen','any activity done indoors','stretching and flexibility work'],a:0,why:'Anaerobic means without oxygen — short, maximal efforts such as a 100 m sprint, producing lactic acid.',tech:'Match the energy system to the event: 100 m anaerobic, marathon aerobic, 800 m a mixture.'},
{id:'pe9',subj:'physical-education',strand:'pe-fitness',level:8,diff:2,q:'Which test measures cardiovascular endurance?',opts:['the multi-stage fitness (bleep) test','the sit-and-reach test','the standing broad jump','the grip dynamometer'],a:0,why:'The bleep test measures aerobic capacity. Sit-and-reach measures flexibility, broad jump power, dynamometer strength.',tech:'Learn one test per fitness component. Questions pair a component with its test almost every year.'},
{id:'pe10',subj:'physical-education',strand:'pe-nutri',level:7,diff:2,q:'During prolonged exercise in Caribbean heat, the greatest immediate risk is:',opts:['dehydration','vitamin deficiency','protein shortage','too much fibre'],a:0,why:'Heavy sweating in high heat and humidity causes fluid and electrolyte loss, which impairs performance and can be dangerous.',tech:'Mention the climate. A Caribbean candidate writing about heat and humidity is answering the real question.'},
{id:'pe11',subj:'physical-education',strand:'pe-injury',level:8,diff:2,q:'Which is a preventative measure rather than a treatment?',opts:['wearing correct protective equipment','applying ice to a sprain','strapping an injured ankle','resting a torn muscle'],a:0,why:'Prevention happens before injury; the other three are responses after it.',tech:'Sort your revision into prevention, immediate treatment and rehabilitation. Questions name one of the three.'},
{id:'pe12',subj:'physical-education',strand:'pe-sport',level:9,diff:2,q:'The use of banned performance-enhancing drugs in sport is primarily an issue of:',opts:['fairness and athlete health','entertainment value','team selection','ticket pricing'],a:0,why:'Doping undermines fair competition and carries serious long-term health risks, which is why it is banned and tested for.',tech:'Give both sides of the argument, then a judgement. "Discuss" questions expect a position at the end.'},

/* ---------------------- INFORMATION TECHNOLOGY ---------------------- */
{id:'it8',subj:'information-technology',strand:'it-hardware',level:6,diff:1,q:'Which is an OUTPUT device?',opts:['plotter','keyboard','mouse','microphone'],a:0,why:'A plotter produces printed drawings — data leaving the computer. The other three send data in.',tech:'Some devices are both, such as a touchscreen. If a question offers one, read the wording carefully.'},
{id:'it9',subj:'information-technology',strand:'it-hardware',level:7,diff:2,q:'The main purpose of an operating system is to:',opts:['manage the hardware and provide a platform for applications','create documents','protect against viruses','connect to the internet'],a:0,why:'The OS manages memory, files, processes and devices, and gives applications a consistent interface to them.',tech:'Name specific functions — memory management, file management, device control. A vague answer scores low.'},
{id:'it10',subj:'information-technology',strand:'it-impact',level:8,diff:2,q:'An e-mail pretending to be from your bank and asking you to confirm your password is:',opts:['phishing','spam','a firewall','encryption'],a:0,why:'Phishing impersonates a trusted organisation to trick you into giving up credentials or card details.',tech:'Be able to state one countermeasure for each threat. Naming the threat alone is half the mark.'},
{id:'it11',subj:'information-technology',strand:'it-database',level:9,diff:2,q:'In a database table, the primary key is the field that:',opts:['uniquely identifies each record','holds the most data','comes first alphabetically','links to the internet'],a:0,why:'A primary key is unique for every record, which is what allows records to be found and related reliably.',tech:'A good primary key never repeats and never changes — an ID number, not a surname.'},
{id:'it12',subj:'information-technology',strand:'it-data',level:8,diff:2,q:'Roughly how many bytes are in one kilobyte?',opts:['1024','100','10','1000000'],a:0,why:'One kilobyte is 2¹⁰ = 1024 bytes, because storage is measured in powers of two.',tech:'Learn the ladder: bit, byte, KB, MB, GB, TB, each 1024 times the last. File-size questions depend on it.'},

/* ------------------------------ GEOGRAPHY ------------------------------ */
{id:'ge9',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'Lines of latitude run:',opts:['east to west, measuring distance north or south of the Equator','north to south, measuring distance east or west','only through the poles','along the Greenwich Meridian'],a:0,why:'Latitude lines are parallel to the Equator and measure how far north or south a place lies. Longitude lines run pole to pole.',tech:'LatitudE is flat like a ladder rung. Trinidad sits at about 10°N, which explains its climate.'},
{id:'ge10',subj:'geography',strand:'ge-tectonic',level:8,diff:2,q:'A waterfall, a gorge and rapids are features of a river’s:',opts:['upper course','lower course','delta','estuary'],a:0,why:'The upper course is steep and fast, eroding vertically to give waterfalls, gorges and V-shaped valleys. Meanders and deltas belong to the lower course.',tech:'Learn the three courses with two features each. Questions almost always name a course.'},
{id:'ge11',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'On a 1:50 000 map, 2 cm represents:',opts:['1 km','500 m','2 km','5 km'],a:0,why:'1 cm represents 50 000 cm, which is 500 m. So 2 cm represents 1 000 m, or 1 km.',tech:'Convert the scale to metres once at the start and write it in the margin. Then every distance is arithmetic.'},
{id:'ge12',subj:'geography',strand:'ge-econ',level:8,diff:2,q:'Which is a DISADVANTAGE of tourism for a Caribbean island?',opts:['pressure on water and waste systems in peak season','creation of employment','earning of foreign exchange','improvement of airports and roads'],a:0,why:'Visitor numbers can exceed what local water supply, sewage and waste disposal were built for. The other three are benefits.',tech:'Prepare three advantages and three disadvantages with a named island. Balance earns the higher band.'},

/* --------------------------- ENGLISH A & B --------------------------- */
{id:'ea11',subj:'english-a',strand:'ea-comp',level:7,diff:2,q:'A topic sentence in a paragraph:',opts:['states the main idea the paragraph will develop','gives an example','concludes the argument','asks a question'],a:0,why:'The topic sentence announces the paragraph’s single main idea, which the rest of the paragraph supports.',tech:'One idea per paragraph. If you find two, split it — examiners reward clear structure.'},
{id:'ea12',subj:'english-a',strand:'ea-vocab',level:8,diff:2,q:'Which sentence is written in the most FORMAL register?',opts:['I am writing to request permission to leave early.','Just letting you know I gotta go early.','Can I bounce early today?','Heads up — leaving early.'],a:0,why:'Formal register avoids contractions and slang and uses complete, courteous constructions.',tech:'Match register to audience. A formal letter with slang in it loses marks no matter how clear the point is.'},
{id:'eb11',subj:'english-b',strand:'eb-prose',level:7,diff:2,q:'The ATMOSPHERE of a setting refers to:',opts:['the feeling the place creates','the time of day','the geographical location','the number of characters present'],a:0,why:'Setting is where and when; atmosphere is the emotional quality the writer builds through detail and word choice.',tech:'Quote the specific words that build the atmosphere. Naming it without evidence earns little.'},
{id:'eb12',subj:'english-b',strand:'eb-poetry',level:8,diff:2,q:'Enjambment in poetry is when:',opts:['a sentence runs past the end of a line without a pause','every line rhymes','a line is repeated','the poem has no punctuation at all'],a:0,why:'Enjambment carries the sense over the line break, which can create momentum, urgency or surprise at the next line.',tech:'Say what the enjambment DOES. "Creates flow" is weak; "hurries the reader into the next image" is not.'},

/* --------------------------- SCIENCES & HISTORY --------------------------- */
{id:'ph11',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'A ball is held above the ground and released. The main energy change is:',opts:['gravitational potential to kinetic','kinetic to chemical','heat to potential','sound to kinetic'],a:0,why:'The stored gravitational potential energy converts to kinetic energy as the ball speeds up while falling.',tech:'Write energy changes as "X energy → Y energy". Examiners look for that exact form.'},
{id:'ph12',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'A force of 200 N acts over an area of 0.5 m². What is the pressure?',opts:['400 Pa','100 Pa','0.0025 Pa','200 Pa'],a:0,why:'Pressure = force ÷ area = 200 ÷ 0.5 = 400 Pa.',tech:'Dividing by a number less than one makes the answer LARGER. If yours got smaller, check the division.'},
{id:'ch11',subj:'chemistry',strand:'ch-matter',level:6,diff:1,q:'In a salt solution, the salt is the:',opts:['solute','solvent','solution','suspension'],a:0,why:'The solute dissolves, the solvent does the dissolving, and together they form the solution.',tech:'Three words, one sentence: solute + solvent = solution. It removes most of the confusion in this topic.'},
{id:'ch12',subj:'chemistry',strand:'ch-mole',level:9,diff:2,q:'Which change would INCREASE the rate of a reaction?',opts:['raising the temperature','using larger lumps of solid','lowering the concentration','removing the catalyst'],a:0,why:'Higher temperature means faster particles and more frequent successful collisions. The other three all slow it down.',tech:'Explain rate through collision theory — more frequent collisions with enough energy. That phrase carries the mark.'},
{id:'bi11',subj:'biology',strand:'bi-nutri',level:7,diff:2,q:'A diet lacking vitamin C leads to:',opts:['scurvy','rickets','anaemia','goitre'],a:0,why:'Vitamin C deficiency causes scurvy. Rickets is vitamin D, anaemia is iron, goitre is iodine.',tech:'Learn deficiency diseases as nutrient-disease pairs. They appear in Paper 01 most years.'},
{id:'bi12',subj:'biology',strand:'bi-repro',level:8,diff:2,q:'Pollination is BEST defined as the transfer of pollen from:',opts:['anther to stigma','stigma to ovule','ovary to anther','petal to sepal'],a:0,why:'Pollination is anther to stigma. Fertilisation happens afterwards, when the male nucleus reaches the ovule.',tech:'Pollination and fertilisation are two different events. Confusing them is the commonest error in this topic.'},
{id:'hi11',subj:'history',strand:'hi-indigenous',level:7,diff:2,q:'The encomienda system in the Spanish Caribbean was:',opts:['a grant of indigenous labour to a Spanish settler','a form of paid employment','a trading agreement between islands','a religious order'],a:0,why:'It granted a settler the labour and tribute of a group of indigenous people, nominally in exchange for protection and instruction. In practice it was forced labour and contributed to catastrophic population decline.',tech:'Link the encomienda to the collapse of the indigenous population and then to the turn to African labour.'},
{id:'hi12',subj:'history',strand:'hi-indep',level:9,diff:3,q:'The West Indies Federation collapsed in 1962 chiefly because:',opts:['Jamaica withdrew after a referendum','Britain dissolved it without warning','the islands ran out of money immediately','no island wanted independence'],a:0,why:'Jamaica’s 1961 referendum voted to leave; Trinidad and Tobago then withdrew, and the Federation was dissolved in 1962.',tech:'Know the deeper causes too — island insularity, freedom of movement, unequal contributions, weak central powers.'}
);

/* ========================= PRIMARY — Standards 1 to 5 =========================
 * Written for the SEA papers: Mathematics (Number, Measurement, Geometry,
 * Statistics), English Language Arts (spelling, punctuation, grammar, reading
 * comprehension) and ELA Writing. Language is pitched at the age, and the
 * reasoning is written to be read by a child, not about one.
 */
window.CSEC_QUESTIONS.push(

/* ---------------------------- MATHEMATICS ---------------------------- */
{id:'pm1',subj:'p-mathematics',strand:'pm-place',level:1,diff:1,q:'What is the value of the 7 in the number 472?',opts:['70','7','700','7000'],a:0,why:'Counting from the right, 2 is ones, 7 is tens and 4 is hundreds. Seven tens is 70.',tech:'Write the headings H T O above the digits before you answer. It takes five seconds and stops the guessing.'},
{id:'pm2',subj:'p-mathematics',strand:'pm-place',level:3,diff:2,q:'Round 3 847 to the nearest hundred.',opts:['3 800','3 900','3 850','4 000'],a:0,why:'Look at the tens digit, which is 4. Four is less than five, so the hundreds digit stays the same and 3 847 becomes 3 800.',tech:'Underline the digit you are rounding to, then look at the ONE digit to its right. Five or more rounds up.'},
{id:'pm3',subj:'p-mathematics',strand:'pm-place',level:4,diff:2,q:'Which number is the largest?',opts:['9 087','9 078','8 987','9 008'],a:0,why:'All start with 9 except 8 987. Compare the hundreds next: 9 087 has 0 hundreds and 8 tens, 9 078 has 0 hundreds and 7 tens. So 9 087 is largest.',tech:'Line the numbers up one under the other and compare from the left. The first column where they differ decides it.'},
{id:'pm4',subj:'p-mathematics',strand:'pm-ops',level:2,diff:1,q:'What is 6 × 7?',opts:['42','48','36','56'],a:0,why:'Six sevens are 42. If you know 6 × 7 you also know 7 × 6 — they give the same answer.',tech:'Learn tables both ways round. It halves what you have to remember.'},
{id:'pm5',subj:'p-mathematics',strand:'pm-ops',level:3,diff:2,q:'A box holds 24 mangoes. How many mangoes are in 15 boxes?',opts:['360','340','240','380'],a:0,why:'24 × 15. Do 24 × 10 = 240 and 24 × 5 = 120, then add: 240 + 120 = 360.',tech:'Split the harder number into tens and ones, multiply each, then add. Much safer than long multiplication under pressure.'},
{id:'pm6',subj:'p-mathematics',strand:'pm-ops',level:4,diff:2,q:'Share 486 sweets equally among 6 children. How many does each child get?',opts:['81','80','76','86'],a:0,why:'486 ÷ 6. Six goes into 48 eight times, and into 6 once, giving 81.',tech:'Check a division by multiplying back: 81 × 6 = 486. If it does not match, you have made a slip.'},
{id:'pm7',subj:'p-mathematics',strand:'pm-fractions',level:2,diff:1,q:'Which fraction is the same as one half?',opts:['2/4','1/3','2/3','3/4'],a:0,why:'Two quarters make one half — cut a roti into four and take two pieces.',tech:'Draw the shape and shade it if you are unsure. A picture settles most fraction questions.'},
{id:'pm8',subj:'p-mathematics',strand:'pm-fractions',level:4,diff:2,q:'What is 1/4 of 60?',opts:['15','20','24','30'],a:0,why:'A quarter means share into 4 equal parts: 60 ÷ 4 = 15.',tech:'"Of" means multiply, and a unit fraction means divide by the bottom number. 1/4 of something is that thing ÷ 4.'},
{id:'pm9',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'What is 3/5 + 1/5?',opts:['4/5','4/10','3/10','2/5'],a:0,why:'The bottom numbers are already the same, so add only the tops: 3 + 1 = 4, giving 4/5. The bottom stays 5.',tech:'Never add the bottom numbers. If the bottoms are different, make them the same FIRST.'},
{id:'pm10',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'What is 0.6 written as a fraction in its simplest form?',opts:['3/5','6/10','1/6','60/10'],a:0,why:'0.6 is six tenths, 6/10. Both 6 and 10 divide by 2, giving 3/5.',tech:'One decimal place means tenths, two places means hundredths. Then simplify.'},
{id:'pm11',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Find 25% of TT$80.',opts:['TT$20','TT$25','TT$16','TT$40'],a:0,why:'25% is the same as one quarter, so 80 ÷ 4 = TT$20.',tech:'Learn the easy ones: 50% is half, 25% is a quarter, 10% is divide by 10. Most SEA percent questions are one of those.'},
{id:'pm12',subj:'p-mathematics',strand:'pm-money',level:2,diff:1,q:'A drink costs TT$4.50. You pay with a TT$10 note. How much change?',opts:['TT$5.50','TT$6.50','TT$4.50','TT$5.00'],a:0,why:'10.00 − 4.50 = 5.50.',tech:'Count up from the price to the note: 4.50 to 5.00 is 50 cents, 5.00 to 10.00 is 5 dollars. That is TT$5.50.'},
{id:'pm13',subj:'p-mathematics',strand:'pm-money',level:4,diff:2,q:'Three books cost TT$27.60 altogether. What does one book cost?',opts:['TT$9.20','TT$9.02','TT$8.20','TT$9.60'],a:0,why:'27.60 ÷ 3 = 9.20.',tech:'Keep the decimal points lined up when you divide money, and always write two figures after the point.'},
{id:'pm14',subj:'p-mathematics',strand:'pm-time',level:3,diff:2,q:'A film starts at 2:45 p.m. and lasts 1 hour 30 minutes. When does it finish?',opts:['4:15 p.m.','4:45 p.m.','3:15 p.m.','4:05 p.m.'],a:0,why:'2:45 plus 1 hour is 3:45. Plus 30 more minutes is 4:15 p.m.',tech:'Add the hours first, then the minutes. If the minutes go past 60, carry an hour.'},
{id:'pm15',subj:'p-mathematics',strand:'pm-time',level:4,diff:2,q:'Write 7:20 p.m. using the 24-hour clock.',opts:['19:20','07:20','17:20','20:07'],a:0,why:'After midday add 12 to the hour: 7 + 12 = 19, so 19:20.',tech:'a.m. hours stay the same. p.m. hours get 12 added — except 12 p.m., which stays 12.'},
{id:'pm16',subj:'p-mathematics',strand:'pm-measure',level:3,diff:2,q:'How many centimetres are in 2.5 metres?',opts:['250 cm','25 cm','2 500 cm','205 cm'],a:0,why:'One metre is 100 cm, so 2.5 × 100 = 250 cm.',tech:'Changing to a SMALLER unit makes the number BIGGER. If your answer got smaller, you divided when you should have multiplied.'},
{id:'pm17',subj:'p-mathematics',strand:'pm-measure',level:4,diff:2,q:'A bottle holds 1.5 litres. How many millilitres is that?',opts:['1 500 ml','150 ml','15 000 ml','1 050 ml'],a:0,why:'One litre is 1 000 ml, so 1.5 × 1 000 = 1 500 ml.',tech:'Learn the three ladders: km-m-cm-mm, kg-g, l-ml. Each step is ×1000 or ×100.'},
{id:'pm18',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A rectangle is 8 cm long and 5 cm wide. What is its area?',opts:['40 cm²','26 cm²','13 cm²','80 cm²'],a:0,why:'Area of a rectangle is length × width: 8 × 5 = 40 cm².',tech:'Area is measured in square units (cm²). Perimeter is the distance all the way round and uses plain cm.'},
{id:'pm19',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A square has sides of 7 cm. What is its perimeter?',opts:['28 cm','49 cm','14 cm','21 cm'],a:0,why:'Perimeter is all four sides added: 7 + 7 + 7 + 7 = 28 cm, or 4 × 7.',tech:'Read carefully whether the question wants perimeter or area. Mixing them up is the commonest mistake in this topic.'},
{id:'pm20',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'A box is 4 cm by 3 cm by 2 cm. What is its volume?',opts:['24 cm³','9 cm³','12 cm³','48 cm³'],a:0,why:'Volume of a cuboid is length × width × height: 4 × 3 × 2 = 24 cm³.',tech:'Volume uses cubic units (cm³) because you multiplied three measurements together.'},
{id:'pm21',subj:'p-mathematics',strand:'pm-shapes',level:2,diff:1,q:'How many faces does a cube have?',opts:['6','8','12','4'],a:0,why:'A cube has six square faces — think of a dice.',tech:'Faces are the flat surfaces, edges are the lines where they meet, vertices are the corners. A cube has 6, 12 and 8.'},
{id:'pm22',subj:'p-mathematics',strand:'pm-shapes',level:3,diff:2,q:'A shape has 3 sides and 3 angles. What is it?',opts:['a triangle','a square','a pentagon','a rectangle'],a:0,why:'Three sides and three angles make a triangle.',tech:'Count the sides to name the shape: 3 triangle, 4 quadrilateral, 5 pentagon, 6 hexagon, 8 octagon.'},
{id:'pm23',subj:'p-mathematics',strand:'pm-angles',level:4,diff:2,q:'An angle that is exactly 90° is called:',opts:['a right angle','an acute angle','an obtuse angle','a straight angle'],a:0,why:'A 90° angle is a right angle — the corner of a book or a door.',tech:'Less than 90° is acute, more than 90° but less than 180° is obtuse, exactly 180° is a straight angle.'},
{id:'pm24',subj:'p-mathematics',strand:'pm-graphs',level:3,diff:2,q:'On a pictograph, one symbol stands for 5 books. A row shows 4 symbols. How many books is that?',opts:['20','9','4','15'],a:0,why:'Each symbol is 5 books, so 4 × 5 = 20.',tech:'ALWAYS read the key first. The commonest pictograph mistake is counting symbols instead of using the key.'},
{id:'pm25',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'Find the mean of 4, 8, 6 and 10.',opts:['7','6','8','28'],a:0,why:'Add them: 4 + 8 + 6 + 10 = 28. There are 4 numbers, so 28 ÷ 4 = 7.',tech:'Mean is add-then-divide. Mode is the one that appears most. Median is the middle one after ordering.'},

/* ------------------------ ENGLISH LANGUAGE ARTS ------------------------ */
{id:'pel1',subj:'p-ela',strand:'pe-spell',level:2,diff:1,q:'Which word is spelled correctly?',opts:['because','becuase','becouse','becasue'],a:0,why:'It is b-e-c-a-u-s-e. The "au" in the middle is what most people get wrong.',tech:'Say the tricky part out loud in syllables: be-cause. Then write it three times.'},
{id:'pel2',subj:'p-ela',strand:'pe-spell',level:4,diff:2,q:'Which word is spelled correctly?',opts:['separate','seperate','seperete','separete'],a:0,why:'It is s-e-p-a-r-a-t-e. There is "a rat" in the middle of separate.',tech:'Find a small word hiding inside a hard word. It gives you something to hold on to.'},
{id:'pel3',subj:'p-ela',strand:'pe-punct',level:2,diff:1,q:'Which sentence is punctuated correctly?',opts:['My friend Anisa lives in Arima.','my friend anisa lives in arima.','My friend anisa lives in Arima','My Friend Anisa lives in arima.'],a:0,why:'A sentence starts with a capital, names of people and places take capitals, and it ends with a full stop.',tech:'Check three things every time: capital at the start, capitals on names, full stop at the end.'},
{id:'pel4',subj:'p-ela',strand:'pe-punct',level:4,diff:2,q:'Which sentence uses speech marks correctly?',opts:['"Where are you going?" asked Mummy.','"Where are you going? asked Mummy."','Where are you going? "asked Mummy".','"where are you going?" asked Mummy.'],a:0,why:'The speech marks go around the spoken words only, the question mark sits inside them, and the spoken words begin with a capital.',tech:'Speech marks wrap only what came out of the mouth. The "asked Mummy" part stays outside.'},
{id:'pel5',subj:'p-ela',strand:'pe-punct',level:5,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The girl’s bag is on the desk.','The girls bag is on the desk.','The girl’s bags is on the desk.','The girls’ bag belongs to her.'],a:0,why:'One girl owns the bag, so the apostrophe goes before the s: girl’s.',tech:'Ask how many owners. One owner → apostrophe then s. More than one → s then apostrophe.'},
{id:'pel6',subj:'p-ela',strand:'pe-grammar',level:2,diff:1,q:'Choose the correct word: "She ___ to school every day."',opts:['walks','walk','walking','walked every tomorrow'],a:0,why:'"She" is one person, so the verb takes an s: she walks. "Every day" tells us it happens regularly.',tech:'He, she and it take a verb with s. I, you, we and they do not.'},
{id:'pel7',subj:'p-ela',strand:'pe-grammar',level:3,diff:2,q:'Which word is a verb in this sentence: "The bright parrot flew over the river."',opts:['flew','bright','parrot','river'],a:0,why:'"Flew" is the doing word — it tells you what the parrot did. Parrot and river are nouns, bright is an adjective.',tech:'Ask "what is happening?" The answer is the verb.'},
{id:'pel8',subj:'p-ela',strand:'pe-grammar',level:4,diff:2,q:'Choose the correct word: "There ___ five boys in the yard."',opts:['were','was','is','be'],a:0,why:'"Five boys" is more than one, so the verb must be plural: were.',tech:'Find what the verb is really about. Here it is "boys", not "there".'},
{id:'pel9',subj:'p-ela',strand:'pe-grammar',level:5,diff:2,q:'Which sentence is in the past tense?',opts:['She bought a pattie at the shop.','She buys a pattie at the shop.','She is buying a pattie.','She will buy a pattie.'],a:0,why:'"Bought" is the past tense of buy — it has already happened.',tech:'Past already happened, present is happening now, future has not happened yet. Check the verb, not the rest.'},
{id:'pel10',subj:'p-ela',strand:'pe-vocab',level:4,diff:2,q:'"The path was narrow." The word "narrow" means:',opts:['not wide','very long','very steep','very dark'],a:0,why:'Narrow is the opposite of wide — there is not much room from side to side.',tech:'If you do not know a word, read the whole sentence again and ask what would make sense there.'},
{id:'pel11',subj:'p-ela',strand:'pe-vocab',level:5,diff:2,q:'"The old man was weary after the long walk." The word "weary" most nearly means:',opts:['very tired','very angry','very hungry','very happy'],a:0,why:'Weary means tired out. The clue is "after the long walk".',tech:'The words around the unknown word are the clue. SEA always leaves one.'},
{id:'pel12',subj:'p-ela',strand:'pe-fiction',level:3,diff:2,q:'In a story, the character who the story is mainly about is called the:',opts:['main character','narrator','author','setting'],a:0,why:'The main character is the person the story follows. The author is the person who wrote it, and the setting is where and when it happens.',tech:'Before answering comprehension questions, note who the story is about and where it happens.'},
{id:'pel13',subj:'p-ela',strand:'pe-fiction',level:4,diff:2,q:'A question asks "How did Maya FEEL when she saw the letter?" but the passage never uses a feeling word. You should:',opts:['work it out from what she said and did','write that the passage does not say','copy the whole sentence about the letter','guess any feeling'],a:0,why:'The writer shows feelings through actions — shaking hands, a quiet voice, running away. You use that evidence to work out the feeling.',tech:'Point to the words in the passage that made you think it. That is what earns the mark.'},
{id:'pel14',subj:'p-ela',strand:'pe-nonfict',level:4,diff:2,q:'In a report about turtles, the best place to find out what turtles eat is:',opts:['the paragraph with a heading about food','the first sentence','the picture caption','the title'],a:0,why:'Headings tell you what each part is about, so you can go straight to the right paragraph instead of reading everything again.',tech:'Read the questions first, then scan the headings. It saves minutes you will need later.'},
{id:'pel15',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"The sun smiled down on Maracas Bay." The sun is being described as if it were:',opts:['a person','an animal','a machine','a building'],a:0,why:'Smiling is something people do, so the poet is describing the sun as if it were a person. That is personification.',tech:'When something that is not alive does a human thing, say so and then say what feeling it gives — here, warmth and happiness.'},
{id:'pel16',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'A bus timetable shows buses at 6:00, 6:30, 7:00 and 7:30. How often does a bus come?',opts:['every 30 minutes','every hour','every 15 minutes','twice a day'],a:0,why:'From 6:00 to 6:30 is 30 minutes, and so is each step after it.',tech:'With a timetable or chart, find the pattern between two entries first, then answer.'},

/* ---------------------------- ELA WRITING ---------------------------- */
{id:'pw1',subj:'p-ela-writing',strand:'pw-narrative',level:3,diff:1,q:'Every good story needs:',opts:['a beginning, a middle and an ending','as many characters as possible','lots of long words','a lot of speech'],a:0,why:'A story that just stops has no ending, and markers notice. Plan all three parts before you start writing.',tech:'Spend two minutes planning three boxes: how it starts, what goes wrong, how it ends. Then write.'},
{id:'pw2',subj:'p-ela-writing',strand:'pw-narrative',level:4,diff:2,q:'Which opening is the most interesting?',opts:['The gate creaked, and I knew somebody had been there.','One day I woke up and got out of bed.','This is a story about my holiday.','I am going to tell you what happened.'],a:0,why:'Starting inside the action makes the reader want to know more. The others just announce that a story is coming.',tech:'Never begin with "This is a story about". Start with something happening.'},
{id:'pw3',subj:'p-ela-writing',strand:'pw-language',level:4,diff:2,q:'Which sentence uses the best describing detail?',opts:['The mango was warm and heavy in my hand.','The mango was nice.','The mango was a mango.','The mango was very very good.'],a:0,why:'"Warm and heavy in my hand" lets the reader feel it. "Nice" and "very very good" tell us nothing.',tech:'Use your senses — what you saw, heard, smelled, felt. One good detail beats three weak ones.'},
{id:'pw4',subj:'p-ela-writing',strand:'pw-language',level:5,diff:2,q:'"The rain fell like drums on the galvanise." This comparison is:',opts:['a simile','a fact','a question','a heading'],a:0,why:'It compares the rain to drums using the word "like", which makes it a simile.',tech:'A simile uses "like" or "as". Use one or two in a story — not one in every sentence.'},
{id:'pw5',subj:'p-ela-writing',strand:'pw-organise',level:4,diff:2,q:'A new paragraph should start when:',opts:['you move to a new idea, time or place','the page looks too full','you have written five lines','you use a new word'],a:0,why:'Paragraphs group ideas. A new idea, a jump in time, a change of place or a new speaker all start a new one.',tech:'If you wrote a whole page with no paragraphs, you lost organisation marks before the marker read a word.'},
{id:'pw6',subj:'p-ela-writing',strand:'pw-expository',level:5,diff:2,q:'An expository piece is different from a story because it:',opts:['explains something using facts','has a hero and a villain','always ends happily','must be written in the first person'],a:0,why:'Expository writing informs or explains — a report on an animal, a place or a process. It uses facts, not plot.',tech:'At SEA the writing paper gives you either three narrative items OR three expository ones. Practise both; you do not get to choose which type appears.'},
{id:'pw7',subj:'p-ela-writing',strand:'pw-mechanics',level:3,diff:2,q:'Before you hand in your writing you should ALWAYS:',opts:['read it through to check capitals and full stops','count the words','rub out the plan','make the writing bigger'],a:0,why:'Grammar and mechanics is one of the four things the markers score. Two minutes of checking usually finds three or four easy marks.',tech:'Read your work in a whisper. Your ear catches mistakes your eye slides past.'},
{id:'pw8',subj:'p-ela-writing',strand:'pw-mechanics',level:5,diff:2,q:'Your SEA writing response is marked on Content, Language Use, Organisation and:',opts:['Grammar and Mechanics','Handwriting speed','Length','Number of characters'],a:0,why:'The four criteria are Content, Language Use, Grammar and Mechanics, and Organisation. Two people mark each response.',tech:'Know what you are marked on. A long piece with no paragraphs and no full stops loses on two of the four.'},

/* ------------------------------ SCIENCE ------------------------------ */
{id:'ps1',subj:'p-science',strand:'ps-living',level:2,diff:1,q:'Which of these is a living thing?',opts:['a hibiscus plant','a stone','a spoon','a bicycle'],a:0,why:'Living things grow, need food and water, and can make more of themselves. A plant does all three.',tech:'Remember MRS GREN — movement, respiration, sensitivity, growth, reproduction, excretion, nutrition.'},
{id:'ps2',subj:'p-science',strand:'ps-living',level:3,diff:2,q:'What do green plants need to make their own food?',opts:['sunlight, water and carbon dioxide','only water','only soil','meat and water'],a:0,why:'Green plants use sunlight, water and carbon dioxide from the air to make their food. That is photosynthesis.',tech:'Plants make food; animals must find it. That one sentence answers a lot of questions.'},
{id:'ps3',subj:'p-science',strand:'ps-body',level:3,diff:2,q:'Which organ pumps blood around the body?',opts:['the heart','the lungs','the stomach','the brain'],a:0,why:'The heart pumps blood. The lungs take in air, the stomach digests food and the brain controls everything.',tech:'Match each organ to one job. Questions usually give you the job and ask for the organ.'},
{id:'ps4',subj:'p-science',strand:'ps-body',level:4,diff:2,q:'Which food group should you eat the MOST of for energy?',opts:['carbohydrates','fats','vitamins','minerals'],a:0,why:'Carbohydrates such as rice, roti, ground provision and bread are the body’s main energy source.',tech:'Learn the groups with local examples: carbohydrates — rice and dasheen; protein — fish and peas.'},
{id:'ps5',subj:'p-science',strand:'ps-matter',level:3,diff:1,q:'Water turning into ice is an example of:',opts:['freezing','melting','evaporation','condensation'],a:0,why:'Liquid becoming solid is freezing. Solid to liquid is melting.',tech:'Draw the three states in a triangle and label the arrows between them. It fixes all four words at once.'},
{id:'ps6',subj:'p-science',strand:'ps-matter',level:4,diff:2,q:'Which is a property of a gas?',opts:['it spreads out to fill its container','it has a fixed shape','it cannot be squashed','it always sinks'],a:0,why:'Gases have no fixed shape or volume and spread to fill whatever holds them. Solids keep their shape; liquids take the shape of the container but keep their volume.',tech:'Three states, three behaviours. Learn shape and volume for each.'},
{id:'ps7',subj:'p-science',strand:'ps-energy',level:4,diff:2,q:'Which material will let electricity pass through it?',opts:['copper wire','a rubber band','a plastic ruler','dry wood'],a:0,why:'Metals such as copper are conductors. Rubber, plastic and dry wood are insulators, which is why wires are covered in plastic.',tech:'Metals conduct; most non-metals do not. That is why plugs are plastic outside and metal inside.'},
{id:'ps8',subj:'p-science',strand:'ps-energy',level:5,diff:2,q:'A magnet will attract:',opts:['an iron nail','a copper coin','a glass marble','a plastic button'],a:0,why:'Magnets attract iron, steel, nickel and cobalt. Copper, glass and plastic are not magnetic.',tech:'Not all metals are magnetic. Copper and aluminium are metals but a magnet ignores them.'},
{id:'ps9',subj:'p-science',strand:'ps-earth',level:4,diff:2,q:'In the water cycle, water turning from liquid into vapour is called:',opts:['evaporation','condensation','precipitation','collection'],a:0,why:'The sun heats water and it evaporates into the air. When it cools it condenses into clouds, then falls as precipitation.',tech:'Learn the cycle as a loop with four labels and draw it. The arrows matter as much as the words.'},
{id:'ps10',subj:'p-science',strand:'ps-earth',level:5,diff:2,q:'Which planet is closest to the Sun?',opts:['Mercury','Venus','Earth','Mars'],a:0,why:'Mercury is first, then Venus, then Earth, then Mars.',tech:'Make a sentence where the first letters match the planets in order. Any silly sentence you invent yourself will stick.'},

/* -------------------------- SOCIAL STUDIES -------------------------- */
{id:'pss1',subj:'p-social-studies',strand:'pss-self',level:1,diff:1,q:'Which of these is a RESPONSIBILITY you have at school?',opts:['keeping your classroom clean','being given a desk','having a teacher','getting a lunch break'],a:0,why:'A responsibility is something you must do. The other three are things you receive, which makes them rights.',tech:'Rights are what you get. Responsibilities are what you must do. Questions test whether you can tell them apart.'},
{id:'pss2',subj:'p-social-studies',strand:'pss-comm',level:3,diff:1,q:'Who is the head of the government of Trinidad and Tobago?',opts:['the Prime Minister','the Mayor','the Principal','the Police Commissioner'],a:0,why:'The Prime Minister heads the government. The President is the Head of State, which is a different role.',tech:'Prime Minister runs the government; President is Head of State. Both appear in questions.'},
{id:'pss3',subj:'p-social-studies',strand:'pss-comm',level:3,diff:2,q:'Which is a national emblem of Trinidad and Tobago?',opts:['the Scarlet Ibis','the flamingo','the parrot','the pelican'],a:0,why:'The Scarlet Ibis is the national bird of Trinidad and the Cocrico is the national bird of Tobago.',tech:'Learn the national emblems as a set: flag, coat of arms, anthem, watchwords, flower, birds.'},
{id:'pss4',subj:'p-social-studies',strand:'pss-comm',level:4,diff:2,q:'Which service is provided by the government for everyone?',opts:['public health care','a private doctor’s office','a supermarket','a private taxi'],a:0,why:'Public services such as health centres, schools, water and roads are provided by the government from taxes.',tech:'Ask who pays. If everybody pays through taxes and everybody may use it, it is a public service.'},
{id:'pss5',subj:'p-social-studies',strand:'pss-geog',level:4,diff:2,q:'Trinidad and Tobago is located in which region?',opts:['the Caribbean','West Africa','Central America','South East Asia'],a:0,why:'Trinidad and Tobago is the southernmost country in the Caribbean, just off the coast of South America.',tech:'Know your position: south of the Caribbean chain, close to Venezuela, with the Atlantic to the east.'},
{id:'pss6',subj:'p-social-studies',strand:'pss-geog',level:5,diff:2,q:'Which is a natural resource of Trinidad and Tobago?',opts:['petroleum and natural gas','motor cars','aeroplanes','mobile phones'],a:0,why:'Oil and natural gas occur naturally and are the country’s most valuable resources. The others are manufactured.',tech:'Natural resources come from the earth or the sea. If a factory made it, it is not one.'},
{id:'pss7',subj:'p-social-studies',strand:'pss-history',level:4,diff:2,q:'Who were the first people to live in Trinidad and Tobago?',opts:['the First Peoples','the Spanish','the British','the French'],a:0,why:'The First Peoples, including the Kalinago and Warao, lived here long before Europeans arrived.',tech:'The order is: First Peoples, then Spanish, then British. Everything else hangs off that sequence.'},
{id:'pss8',subj:'p-social-studies',strand:'pss-history',level:5,diff:2,q:'Emancipation Day in Trinidad and Tobago is celebrated on:',opts:['1 August','31 August','30 May','24 September'],a:0,why:'Emancipation Day is 1 August, marking the end of slavery. Independence Day is 31 August and Indian Arrival Day is 30 May.',tech:'Three national days, three different events. Learn the date with the reason, not on its own.'},
{id:'pss9',subj:'p-social-studies',strand:'pss-citizen',level:3,diff:2,q:'Living in a country where people follow many different religions means we should:',opts:['respect beliefs that are not our own','ask everyone to change','only speak to people like us','ignore other festivals'],a:0,why:'Trinidad and Tobago is a plural society. Respecting difference is what allows people to live together peacefully.',tech:'Name real festivals — Divali, Eid, Christmas, Hosay — when a question asks about the plural society.'},
{id:'pss10',subj:'p-social-studies',strand:'pss-citizen',level:5,diff:2,q:'Which action shows good citizenship?',opts:['reporting a burst water main to the authorities','ignoring litter in the street','keeping to yourself always','taking what you need from a neighbour'],a:0,why:'Good citizens look after shared property and help their community, not only themselves.',tech:'Give an example from your own community in the answer. It lifts a general answer into a good one.'}
);
